window.TURATH_JK(1,{"6":["قال الله تعالى:﴿وَمَا زَادَهُمْ إِلَّا إِيمَانًا وَتَسْلِيمًا﴾[سورة الأحزاب: 22].","وقال جلّ ذكره:﴿وَيَزْدَادَ الَّذِينَ آمَنُوا إِيمَانًا﴾[سورة المدثر: 31].","وقال تبارك وتعالى:﴿فَأَمَّا الَّذِينَ آمَنُوا فَزَادَتْهُمْ إِيمَانًا﴾[التوبة: 124].","وقال تعالى:﴿فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا﴾[سورة آل عمران: 731].","وقال تعالى:﴿لِيَزْدَادُوا إِيمَانًا مَعَ إِيمَانِهِمْ﴾[سورة الفتح: 4]."],"8":["قال الله تعالى: ﴿قَالَتِ الْأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا﴾ [سورة الحجرات: 14].","فإذا كان على الحقيقة فهو على قوله جلّ ذكره: ﴿إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ﴾ [سورة آل عمران: 19]."],"27":["قال الأوزاعيّ: قال الله تعالى: ﴿لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِنْ شَاءَ اللَّهُ آمِنِينَ﴾ [سورة الفتح: 27].قال: قد علم الله تعالى أنهم سيدخلون، وقد قال: ﴿إِنْ شَاءَ اللَّهُ﴾."],"61":["قال الله تعالى: ﴿وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى شَهِدْنَا أَنْ تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ﴾ [سورة الأعراف: 172].","ومعنى الآية: وإذ أخذ ربّك من بني آدم من ظهورهم ذريّتهم وأشهدهم على أنفسهم: ألستُ بربِّكم؟ قالوا: بلى، فقال الله وملائكتُه: شهدنا عليكم بإقراركم بالله ربّكم كيلا تقولوا يوم القيامة: إنّا كنا عن هذا غافلين. انظر: ابن جرير الطبريّ (10/564).","وقال إسحاق بن راهويه: أجمع أهل العلم أن الله خلق الأرواح قبل الأجساد، وأنه استنطقهم وأشهدهم أي على ربوبيته.","وقال ابن الأنباريّ: مذهب أهل الحديث وكبراء أهل العلم في هذه الآية أن الله أخرج ذرية آدم من صلبه، وصلب أولاده، وهم في صور الذّر فأخذ عليهم الميثاق أنه خالقهم وأنهم مصنوعون، فاعترفوا بذلك وقبلوا."],"62":["قال الله تعالى: ﴿وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ﴾ [سورة الأعراف: 200، فصلت: 36]. النَّزْغ والهمْز: الوسوسة.","وقوله سبحانه حاكياً عن يوسف عليه السّلام: ﴿مِنْ بَعْدِ أَنْ نَزَغَ الشَّيْطَانُ بَيْنِي وَبَيْنَ إِخْوَتِي﴾ [سورة يوسف: 100].أي أفسد وأغرى.","وقوله تعالى: ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ مَلِكِ النَّاسِ إِلَهِ النَّاسِ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ مِنَ الْجِنَّةِ وَالنَّاسِ﴾[سورة النّاس:1، 6 ]. والخنّاس هو الشّيطان يوسوس في صدر المرء، فإذا ذكر الله خنس، أي انقبض وتأخّر."],"65":["قال الله تعالى: ﴿وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا﴾[سورة النساء: 36].","وقال تعالى ﴿يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ﴾ [سورة البقرة: 21].","وقال تعالى: ﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ﴾ [سورة الذّاريات: 56].","وغيرها من الآيات وهي كثيرة في كتاب الله، لأنّ دعوة الأنبياء عليهم السّلام كانت لتوحيد الإلهية.","قال شيخ الإسلام ابنُ تيمية رحمه الله تعالى إنّ عامة المتكلمين الذين يقررون التوحيد في كتب الكلام والنظر غايتهم أن يجعلوا التوحيد ثلاثة أنواع: فيقولون: هو واحد في ذاته لا قسيم له، وواحد في صفاته لا شبيه له، وواحد في أفعاله لا شريك له، وأشهر الأنواع الثلاثة عندهم هو الثالث وهو توحيد الافعال، وهو أن خالق العالم واحد، وهم يحتجون على ذلك بما يذكرونه من دلالة التمانع وغيرها، ويظنّون أن هذا هو التوحيد المطلوب، وأنّ هذا هو معنى قولنا: لا اله الا الله حتى يجعلوا معنى الإلهية القدرة على الاختراع، ومعلوم أنّ المشركين من العرب الذين بُعث اليهم محمد صلى الله عليه وسلم أولاً لم يكونوا يخالفونه في هذا، بل كانوا يقرّون بأنّ الله خالقُ كلِّ شىء، حتّى إنّهم كانوا يقرّون بالقدر أيضا وهم مع هذا مشركون. انظر: مجموع الفتاوى (3/98).","أحاديث هذا الباب كثيرة ستُذكر في مواضعها، وهنا أكتفي بذكر بعضها."],"67":["قال الله تعالى: ﴿فَلَا تَجْعَلُوا لِلَّهِ أَنْدَادًا وَأَنْتُمْ تَعْلَمُونَ﴾ [البقرة: 22]."],"70":["قال الله تعالى: ﴿وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ﴾ [سورة الأعراف: 180].","وقال تعالى:﴿قُلِ ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَنَ أَيًّا مَا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَى﴾[سورة الإسراء: 110]. قوله:﴿فَادْعُوهُ بِهَا﴾ والدّعاء هو العبادة."],"73":["قال الله تعالى: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾ [سورة البقرة: 255].","وقال تعالى: ﴿وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ﴾ [سورة الفرقان: 58].","وقال تعالى: ﴿وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ﴾ [سورة طه: 111].","والآيات في هذا المعنى كثيرة."],"74":["قال الله تعالى فيما يقوله حملة العرش:﴿رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا﴾ [سورة غافر: 7].","وقال الله تعالى:﴿إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ﴾ [سورة لقمان: 34].","وقال تعالى:﴿إِنَّمَا الْعِلْمُ عِنْدَ اللَّهِ﴾ [سورة الملك: 26].","وقال تعالى:﴿وَأَضَلَّهُ اللَّهُ عَلَى عِلْمٍ﴾ [سورة الجاثية: 23].","قال ابن عباس: أضلّه الله في سابق علمه.","وقال في قوله تعالى:﴿يَعْلَمُ السِّرَّ وَأَخْفَى﴾ [سورة طه: 7]: يعلم ما أسرّ ابن آدم في نفسه، وما خفى على ابن آدم مما هو فاعله قبل أن يعمله، فالله تعالى يعلم ذلك كلّه، وعلمه فيما مضى من ذلك وما بقي علم واحد.","وقال أيضاً: فإنّه يعلم السّر في نفسك، ويعلم ما تعمل غداً.","وحكى المزنيّ عن الشّافعيّ في قوله تعالى:﴿وَمَا جَعَلْنَا الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْهَا إِلَّا لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ﴾ [سورة البقرة: 143]: يقول: إلاّ لنعلم أن قد علمتم من يتبع الرّسول، وعلم الله تعالى كان قبل اتباعهم وبعده سواء. وقال غيره: إلا لنعلم من يتبع الرسول بوقوع الاتباع منه كما علمناه قبل ذلك أنه يتبعه. انظر: الأسماء والصّفات (1/310، 311).","وقال مالك رحمه الله تعالى: الله في السّماء، وعلمه في كلّ مكان لا يخلو منه شيءٌ. السنة لعبدالله بن أحمد (532)."],"75":["قال الله تعالى: ﴿تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ [سورة الملك: 1].","وقال تعالى: ﴿قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ﴾ [سورة الأنعام: 65].","وقال تعالى: ﴿بَلَى قَادِرِينَ عَلَى أَنْ نُسَوِّيَ بَنَانَهُ﴾ [سورة القيامة: 4]."],"76":["قال الله تعالى: ﴿وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ [سورة البقرة:٢٥٥].","وقال تعالى: ﴿يُدَبِّرُ الْأَمْرَ مِنَ السَّمَاءِ إِلَى الْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ﴾ [السجدة: 5].","وقال تعالى: ﴿تَعْرُجُ الْمَلَائِكَةُ وَالرُّوحُ﴾ [سورة المعارج: 4].","وقال تعالى: ﴿يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ﴾ [سورة النحل: 50].","وقال تعالى: ﴿أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ﴾ [سورة الملك: 16]."],"77":["قال تعالى: ﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾ [سورة طه: 5].","وقال تعالى: ﴿ثُمَّ اسْتَوَى عَلَى الْعَرْشِ﴾ [سورة الأعراف: 54، يونس: 3، الرعد: 2، الفرقان: 59، السجدة: 4، الحديد: 4].","ومعنى قوله: ﴿ثُمَّ اسْتَوَى عَلَى الْعَرْشِ﴾ علا على العرش.","قال ابن عباس: الكرسيّ موضع القدمين، والعرش لا يقدر أحدٌ قدره.","رواه الحاكم (3116) وصحّحه وقال: على شرط الشيخين، وأورده الذهبي في العلو (148) وقال: رواته ثقات.","ولما قبض رسول الله صلى الله عليه وسلم قال أبو بكر الصدّيق رضي الله عنه: أيُّها النّاس إن كان محمد إلهكم الذي تعبدون فإنه قد مات، وإن كان إلهكم الذي في السماء فإنّ إلهكم حيٌّ لا يموت، ثم تلا: ﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ﴾ [سورة آل عمران: 144]. رواه البزّار في البحر الزّخار (103) وقال الهيثميّ في المجمع (14276): رواه البزّار، ورجاله رجال الصّحيح غير علي بن المنذر وهو ثقة.","قلت: وقد تُوبع، فقد رواه الدّارميّ في الرّد على الجهميّة (78) عن عبدالله بن أبي شيبة كلاهما، أعني علي بن المنذر، وعبدالله بن أبي شيبة، عن محمد بن فضيل، عن أبيه، عن نافع، عن ابن عمر، عن أبي بكر، فذكره. واللّفظ للدارميّ، ولفظ البزّار أطول.","وقال ابن خزيمة: نحن نؤمن بخبر الله، جلّ وعلا، أنّ خالقنا مستوٍ على عرشه، لا نبدّل كلام الله، ولا نقول قولاً غير الذي قيل لنا، كما قالت الجهمية المعطّلة: إنّه استولى على عرشه لا استوى، فبدّلوا قولاً غير الذي قيل لهم، لفعل اليهود كما أُمروا أن يقولوا: حطّة، فقالوا: حنطة، مخالفين لأمر الله جلّ وعلا، كذلك الجهمية. كتاب التوحيد (1/230).","وقال الحافظ الذهبيّ رحمه الله تعالى في كتابه العلو (261):","ومما يدل على أن الباري تعالى عال على الأشياء فوق عرشه المجيد غير حال في الأمكنة، قوله تعالى: ﴿وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ [سورة البقرة: 255]، وقال: ﴿وَهُوَ الْعَلِيُّ الْكَبِيرُ﴾ [سورة سبأ: 23]، وقال: ﴿عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ﴾ [سورة الرعد: 9]، وقال: ﴿سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى﴾ [سورة الأعلى: 1]. وقد أمرنا نبيُّنا أن نقول إذا سجدنا: سبحان ربي الأعلى. وقال تعالى في وصف الشهداء ﴿أَحْيَاءٌ عِنْدَ رَبِّهِمْ﴾ [سورة آل عمران: 169]، وقالت امرأة فرعون: ﴿رَبِّ ابْنِ لِي عِنْدَكَ بَيْتًا فِي الْجَنَّةِ﴾ [سورة التحريم: 11]","وفي الصّحيحين، كذا قال، (والصّواب عند أبي داود (3854)، وأحمد (12406): أنّ النّبيّ صلى الله عليه وسلم دعا لقوم فقال: أكلَ طعامَكم الأبرار، وأفطر عندكم الصّائمون، وصلّت عليكم الملائكة، وذكركم الله فيمن عنده.","قال تعالى: ﴿إِنَّ الَّذِينَ عِنْدَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِ﴾ [سورة الأعراف: 206]، وقال: ﴿وَلَهُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ وَمَنْ عِنْدَهُ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِ﴾ [الأنبياء: 19].","وفي صحيح مسلم (430) من حديث جابر بن سمرة مرفوعاً: ألا تصفُّون كما تصُفُّ الملائكةُ عند ربّهم، يتمّون الأوّل فالأوّل، ويتراصّون في الصّف.","وفي صحيح مسلم (2652) من طريق يزيد بن هرمز، عن الأعرج، عن أبي هريرة، قال: قال رسول الله صلى الله عليه وسلم: احتجّ آدمُ وموسى عند ربِّهما وذكر الحديث.","قلت: لقد تمّ تخريج جميع هذه الأحاديث التي أوردها الذّهبيّ في مواضعها، وفي هذه الآيات والأحاديث دليل على اختصاص بعض المخلوقات بالعنديّة له سبحانه وتعالى، وفيه دليل على إثبات علوه سبحانه وتعالى، كما هو مستلزم لنفي وجود الله في كلّ مكان، وعند جميع المخلوقات حسب ما يدّعيه الحلوليون وأصحاب وحدة الوجود."],"80":["قال الله تعالى:﴿وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ﴾ [سورة الرحمن: 27].","وقال تعالى:﴿كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ﴾ [سورة القصص: 88].","وقال تعالى:﴿وَمَا آتَيْتُمْ مِنْ زَكَاةٍ تُرِيدُونَ وَجْهَ اللَّهِ﴾ [سورة الروم: 39].","وقال تعالى:﴿إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللَّهِ﴾ [سورة الإنسان: 9].","وقال تعالى:﴿وَالَّذِينَ صَبَرُوا ابْتِغَاءَ وَجْهِ رَبِّهِمْ﴾ [سورة الرعد: 22].","وقال تعالى:﴿يُرِيدُونَ وَجْهَهُ﴾ [سورة الكهف: 28].","وقال تعالى:﴿إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَى﴾ [سورة الليل: 20].","وغيرها من الآيات البيّنات."],"82":["قال تعالى: ﴿لَقَدْ سَمِعَ اللَّهُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ﴾ [سورة آل عمران: 181]","وقال الله عزّ وجلّ في قصة المجادلة: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ [سورة المجادلة: 1].","وقال الله عزّ وجلّ مخاطباً موسى وهارون: ﴿قَالَ لَا تَخَافَا إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾ [سورة طه: 46].","وقال تعالى: ﴿قَالَ كَلَّا فَاذْهَبَا بِآيَاتِنَا إِنَّا مَعَكُمْ مُسْتَمِعُونَ﴾ [سورة الشّعراء: 15].","وقال تعالى: ﴿وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ﴾ [التوبة: 105].","وقال تعالى: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾ [الشورى: 11]."],"83":["قال تعالى: ﴿وَقَالَتِ الْيَهُودُ يَدُ اللَّهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا بِمَا قَالُوا بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنْفِقُ كَيْفَ يَشَاءُ﴾ [سورة المائدة: 64].","وقال تعالى لإبليس: ﴿مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ﴾ [سورة ص: 75].","وقال تعالى: ﴿فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ﴾ [يس: 83].","وقال تعالى: ﴿وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ [سورة آل عمران: 26]."],"84":["قال الله تعالى: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾ [سورة الزمر: 67]. قال مجاهد: وكلتا يدي الرّحمن يمين."],"88":["قال الله تعالى: ﴿يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ﴾ [سورة الفتح: 10]."],"89":["قال تعالى: ﴿وَتَقُولُ هَلْ مِنْ مَزِيدٍ﴾ [سورة ق: 30]."],"90":["قال الله تعالى: ﴿يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلَا يَسْتَطِيعُونَ خَاشِعَةً أَبْصَارُهُمْ﴾ [سورة القلم: 42، 43]."],"96":["قال الله تعالى: ﴿إِنَّ اللَّهَ لَا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا﴾ [سورة البقرة: 26]."],"98":["قال الله تعالى: ﴿وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّى يَسْمَعَ كَلَامَ اللَّهِ﴾ [سورة التوبة: 6].","وقال تعالى: ﴿وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا﴾[سورة النساء: 164].","وقال تعالى: ﴿قَالَ يَا مُوسَى إِنِّي اصْطَفَيْتُكَ عَلَى النَّاسِ بِرِسَالَاتِي وَبِكَلَامِي فَخُذْ مَا آتَيْتُكَ وَكُنْ مِنَ الشَّاكِرِينَ﴾ [سورة الأعراف: 144].","يقول البيهقيّ رحمه الله تعالى: فهذا كلام سمعه موسى عليه السّلام بإسماع الحقّ إياه بلا ترجمان بينه وبينه. الأسماء والصفات (1/485).","إنّ الكلام صفة من صفات الله تعالى فهولم يزل متكلّماً إذا شاء، ومتى شاء، وكيف شاء، وبما شاء، وهو يتكلّم بحرف وصوت يسمع، وإنّ كلامه قديم.","قلت: لقد خاطب الله موسى بقوله: ﴿فَلَمَّا أَتَاهَا نُودِيَ يَا مُوسَى إِنِّي أَنَا رَبُّكَ فَاخْلَعْ نَعْلَيْكَ إِنَّكَ بِالْوَادِ الْمُقَدَّسِ طُوًى وَأَنَا اخْتَرْتُكَ فَاسْتَمِعْ لِمَا يُوحَى إِنَّنِي أَنَا اللَّهُ لَا إِلَهَ إِلَّا أَنَا فَاعْبُدْنِي وَأَقِمِ الصَّلَاةَ لِذِكْرِي﴾ [سورة طه: 11، 12].","وفي سورة النمل: ﴿يَا مُوسَى إِنَّهُ أَنَا اللَّهُ الْعَزِيزُ الْحَكِيمُ﴾ [سورة النمل: 9].","وجاء في سورة القصص: ﴿فَلَمَّا أَتَاهَا نُودِيَ مِنْ شَاطِئِ الْوَادِ الْأَيْمَنِ فِي الْبُقْعَةِ الْمُبَارَكَةِ مِنَ الشَّجَرَةِ أَنْ يَا مُوسَى إِنِّي أَنَا اللَّهُ رَبُّ الْعَالَمِينَ﴾ [القصص: 30].","ففي هذه الآيات خاطب الله موسى عليه السلام وكلّمه بصوت وحرف مسموع، وغير جائز أن يخاطب ملك مقرّب أو غير مقرّب أو أي مخلوق آخر بقوله: ﴿إِنِّي أَنَا اللَّهُ رَبُّ الْعَالَمِينَ﴾."],"101":["قوله: إِلَّا وَحْيًا وهو شاملٌ للوحي الذي يُلقي الله عز وجل على قلوب الأنبياء والرسل في حال اليقظة، ويشمل أيضا للوحي الذي يُريهم الله في المنام كما قالت عائشة: أول ما بُدئَ به رسول الله صلى الله عليه وسلم الرؤيا الصادقة في النوم.","قال الشّافعيّ: قال غير واحد من أهل التفسير: رؤيا الأنبياء وحيٌّ، لقول ابن إبراهيم الذي أُمر بذبحه: افعل ما تؤمر الأسماء والصّفات (1/491)","وفي صحيح البخاريّ (138) عن عبيد بن عمير، وهو من كبار التابعين، يقول: ﴿رؤيا الأنبياء وحيٌّ ثم قرأ إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ﴾ وقول الحافظ في الفتح (1/239) رواه مسلم مرفوعًا لم أجده في صحيحه، فلعله أراد به معنى الحديث.","وقد رُوي عن ابن عباس مرفوعاً وموقوفاً.","فأمّا المرفوع فرواه ابنُ أبي حاتم، قال: حدّثنا علي بن الحسين بن الجنيد، حدّثنا أبو عبدالملك الكرندي، عن سفيان بن عيينة، عن إسرائيل بن يونس، عن سماك، عن عكرمة، عن ابن عباس، قال: قال رسول الله صلى الله عليه وسلم: رؤيا الأنبياء في المنام وحيٌّ.","أورده ابن كثير في تفسير سورة الصّافات وقال: ليس هو في شيء من الكتب الستة من هذا الوجه.","قلت: لم أقف على ترجمة أبي عبدالملك الكرندي، ولم يذكره المزّيّ من الرواة عن سفيان بن عيينة، وسماك هو ابن حرب وروايته عن عكرمة مضطربة.","وأمّا الموقوف فهو ما رواه الطبرانيّ في المعجم الكبير (12302) عن عبدالله ابن محمد بن سعيد بن أبي مريم، ثنا محمد بن يوسف الفريابيّ، ثنا سفيان، عن سماك ابن حرب، عن سعيد بن جبير، عن ابن عباس قال: رؤيا الأنبياء وحيٌّ.","قال الهيثميّ في المجمع (11737): شيخ الطبرانيّ وهو عبدالله بن محمد بن سعيد بن أبي مريم ضعيف، وبقية رجاله رجال الصّحيح إلا أنه توبع فقد رواه الحاكم (3613) من وجه آخر عن سفيان بإسناده وقال: صحيح على شرط الشيخين.","وقوله تعالى: ﴿أَوْ مِنْ وَرَاءِ حِجَابٍ﴾ هو كما كلّم الله موسى عليه السّلام من وراء حجاب. والحجاب المذكور في هذا الموضع وغيره يرجع إلى الخلق دون الخالق."],"102":["القرآن كلام الله، وكلام الله صفة من صفات ذاته، وليس شيءٌ من صفات ذاته مخلوقاً، ولا محدثاً، ولا حادثاً. والأدلّة على ذلك من كلام الله: ﴿إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ﴾ [سورة النحل: 40] فلو كان القرآن مخلوقاً لكان مخلوقاً بكن، ويستحيل أن يكون قول الله لشيء بقول، لأنه يوجب قولاً ثانياً وثالثا فيتسلسل وهو فاسد.","وقال تعالى: ﴿الرَّحْمَنُ عَلَّمَ الْقُرْآنَ خَلَقَ الْإِنْسَانَ﴾ [سورة الرحمن: 1ـ 3] فخصّ القرآن بالتعليم لأنه كلامه وصفته، وخصّ الإنسان بالتخليق لأنه خلقه ومصنوعه ولو لا ذلك لقال: خلق القرآن والإنسان.","وقال تعالى: ﴿وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا﴾ [سورة النساء: 164] ولا يجوز أن يكون كلام المتكلّم قائماً بغيره.","وقد أنكر الله تعالى قول المشركين ﴿إِنْ هَذَا إِلَّا قَوْلُ الْبَشَرِ﴾ [سورة المدثر: 25] فمن زعم أن القرآن مخلوق فقد جعله قولاً للبشر."],"104":["قال الله تعالى: ﴿عَالِمُ الْغَيْبِ فَلَا يُظْهِرُ عَلَى غَيْبِهِ أَحَدًا﴾ [سورة الجن: 26].","وقال تعالى: ﴿إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ﴾ [سورة لقمان: 34].","وقال تعالى: ﴿أَنْزَلَهُ بِعِلْمِهِ﴾ [سورة النساء: 166].","وقال تعالى: ﴿وَمَا تَحْمِلُ مِنْ أُنْثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ﴾ [سورة فاطر: 11، سورة فصلت: 47]۔","وقال تعالى: ﴿إِلَيْهِ يُرَدُّ عِلْمُ السَّاعَةِ﴾ [سورة فصلت: 47]."],"105":["قال الله تعالى: ﴿وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ﴾ [سورة الحديد: 4].","وقال تعالى: ﴿مَا يَكُونُ مِنْ نَجْوَى ثَلَاثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَا أَدْنَى مِنْ ذَلِكَ وَلَا أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا﴾ [سورة المجادلة: 7].","وقال الله لموسى وهارون حين أرسلهما إلى فرعون: ﴿لَا تَخَافَا إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾ [سورة طه: 46].","وحكى الله قول رسوله محمد صلى الله عليه وسلم حين قال لصاحبه أبي بكر: ﴿إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا﴾ [التوبة: 40]."],"106":["قال الله تعالى: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾ [سورة الشّورى: 11].","وقال تعالى: ﴿هَلْ تَعْلَمُ لَهُ سَمِيًّا﴾ [سورة مريم: 65].","وقال تعالى: ﴿فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ﴾ [سورة النحل: 74].","ضلّتْ طائفتان في أسماء الله تعالى وصفاته.","إحداهما: المشبّهة وهم الذين شبّهوا الله بخلقه، وجعلوا صفاته من جنس صفات المخلوقين.","وأوّل من أظهر هذه المقالة هو هشام بن الحكم الرافضي، مات بعد نكبة البرامكة بمديدة مستترا ويقال: عاش إلى خلافة المأمون، وبيان بن سمعان التميمي وهو أيضا من غلاة الشيعة، كان يقول بألوهية عليٍّ، ومن بعده من أولاده، وكان يقول: إنّ معبوده نور، وصورته صورة إنسان، وله أعضاء كأعضاء الإنسان، وأن جميع أعضائه تفنى إلا الوجه.","وهذان أخذا هذه المقالة من النصارى والهندوس الذي شبّهوا الله تعالى بالمخلوقين.","والثانية: المعطّلة الذين نفوا عن الله جميع صفاته التي وصف بها نفسه، ووصف به رسوله زاعمين أن إثباتها يؤدّي إلى التشبيه والتجسيم.","وأوّلُ من دعا إلى هذه المقالة الجعد بن درهم، فأنكر تكليم الله موسى بكلام مسموع، فرُفِعَ أمره إلى خالد بن عبد الله القشري، وكان أميرًا على العراق من قبل هشام بن عبد الملك بن مروان، ففي يوم عيد الأضحى صعِدَ المنبر، فخطب خطبة بليغةً، ثم قال: ارجعوا فضحّوا تقبّل الله منكم، فإني مُضَحٍّ بالجعد بن درهم، إنه زعم أن الله لم يكلّم موسى تكليما، ولم يتخذْ إبراهيم خليلاً، ثم نزل وذكّاه تحت المنبر من محضر من الخاصة والعامة، فاستحسن الكلُّ فعلَه، وذلك في سنة 124هـ.","هذه القصة ذكرها البخاري في خلق أفعال العباد (رقم 3)، واللالكائي في اعتقاد أهل السنة (2/319)، والدارمي في الرد على الجهمية (ص 21)، والبيهقي في السنن الكبرى (10/205) كلهم من طرقٍ عن عبدالرحمن بن محمد بن حبيب بن أبي حبيب، عن أبيه، عن جده حبيب بن أبي حبيب قال: خطبنا خالدُ بنُ عبد الله القسري بواسط يوم الأضحى فذكره.","وعبدالرحمن وأبوه مجهولان إلا أن هذه القصّة اشتهرتْ بين الناس، فاستغنتْ عن ذكر الإسناد.","ذكره أيضا الذهبي في سير أعلام النبلاء (5/432) في ترجمة خالد بن عبدالله بن يزيد القسري الدمشقي أمير العراق لهشام، وقال: هذه من حسناته.","وأخذ عن الجعد بن درهم هذا المذهب الجهم بن صفوان (128هـ)، ونُسِبَ إليه هذا المذهب، وتأثّرَ بهذه المقالةِ كلٌّ من المعتزلة، والأشاعرة.","فالمعطّلة ينفون عن الله جميع الأسماء والصفات.","والمعتزلة يُثبتون الأسماء المجرّدة عن معانيها، وينفون عنه الصفات.","والأشاعرة يُثبتون الأسماء وسبع صفات فقط وهي: العلم، والحياة، والقدرة، والإرادة، والسمع، والبصر، والكلام، وينفون عنه بقية الصفات.","وشبهة هولاء فيما نفوه من الصفات أن إثباتها يقتضي التشبيه والتجسيم حسب زعمهم، ويسمّون من أثبتها مشبّهة ومجسّمة.","وهدَى اللهُ أهلَ السنة والجماعة، فإنهم يُثبتون من الأسماء والصفات ما أثبتَه اللهُ لنفسه، أو أثبتَ له رسولُه من غير تحريفٍ، ولا تأويلٍ، ولا تشبيهٍ."],"113":["قال الله تعالى: ﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ﴾ [القيامة: 22، 23].","وقال تعالى عن الكّفّار: ﴿كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ ثُمَّ إِنَّهُمْ لَصَالُو الْجَحِيمِ ثُمَّ يُقَالُ هَذَا الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ﴾ [المطّففين: 15، 17]. أي: الكفّار.","قال الشّافعيّ: هذه الآية دليل على أنّ المؤمنين يرونه عزّ وجلّ يومئذ.","قال ابن كثير: وهذا الذي قاله الإمام الشّافعيّ رحمه الله تعالى في غاية الحسن، وهو استدلال بمفهوم هذه الآية، كما دلّ عليه منطوق قوله ﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ﴾، وكما دلّت على ذلك الأحاديث الصّحاح المتواترة في رؤية المؤمنين ربّهم عزّ وجلّ في الدّار الآخرة رؤية بالأبصار في عرصات القيامة، وفي روضات الجنات الفاخرة","قلت: وذلك كرامة منه لهم.","وقوله تعالى: ﴿لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ﴾ [يونس: 26]، فقد رُوي أن الزيادة هي النظر إلى الله سبحانه وتعالى وأسند إلى أبي بكر الصديق وغيره من الصّحابة والتّابعين.","قول الأئمة من أهل السنة في رؤية الله تبارك وتعالى يوم القيامة:","قال مالك رحمه الله تعالى: الناس ينظرون إلى الله تعالى يوم القيامة بأعينهم. الشّريعة للآجريّ (574).","وقال الإمام أحمد: من قال: إنّ الله تعالى لا يُرى في الآخرة فقد كفر، وعليه لعنة الله وغضبه. أليس الله عزّ وجلّ يقول: ﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ﴾ وقال تعالى: ﴿كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ﴾ هذا دليل على أنّ المؤمنين يرون الله تعالى. الشّريعة للآجريّ (577).","وأمّا قوله تعالى: ﴿لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ﴾ [سورة الأنعام: 103] فمعناه عند أهل العلم أي لا تحيط به الأبصار ولا تحويه عزّ وجلّ، وهم يرونه من غير إدراك، ولا يشكّون في رؤيته كما يقول الرّجل: رأيتُ السمّاء. وهو صادق، ولم يحط بصرُه بكلّ السماء ولم يدركها، وكما يقول الرّجل: رأيت البحر، وهو صادق، ولم يدركه بصره كلّ البحر، ولم يُحطه ببصره. ذكره الآجريّ في الشّريعة (2/1048)."],"114":["لم يصحّ شيءٌ في هذا الباب.","وأمّا ما رُوي عن أبي سعيد الخدريّ مرفوعاً: اتقوا فِراسة المؤمن فإنّه ينظر بنور الله. ثم قرأ ﴿إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْمُتَوَسِّمِينَ﴾ [الحجر: 75]. فهو ضعيف.","رواه الترمذيّ (3127) من طريق عطية، عن أبي سعيد.","وقال: هذا حديث غريب، إنّما نعرفه من هذا الوجه.","قلت: عطية هو ابن سعد العوفيّ ضعيف، يدلّس عن الضعفاء، وقد ثبت تدليسه عن أبي سعيد الكلبي وغيره من المتروكين.","وقد رُوي هذا الحديث أيضاً عن عدد من الصّحابة منهم: أبو أمامة الباهليّ، وأبو هريرة، وعبدالله بن عمر، وثوبان، وغيرهم. وأمثلها حديث أبي أمامة.","رواه الطبرانيّ في الكبير (7497) من طريق عبدالله بن صالح، حدثني معاوية بن صالح، عن راشد بن سعد، عن أبي أمامة.","وفيه عبدالله بن صالح وهو كاتب اللّيث قال فيه الإمام أحمد: كان متماسكاً ثم فسد، وقال أبوحاتم: أرى الأحاديث التي أنكرت عليه مما افتعل خالد بن نُجيح، وكان يصحبه، ولم يكن أبو صالح ممن يكذب، وكان رجلاً صالحاً. وقال النسائيّ: ليس بثقة، ومشّاه يحيى بن معين وغيره.","قلت: لقد انفرد أبو صالح بهذا الحديث، فلا يبعد أن يكون مما افتعله خالد بن نجيح ودسّّه في كتبه، فحدّث به وهو لا يدري مع ما يحمله متن الحديث من النّكارة في الألفاظ.","وفي الباب أيضاً حديث ثوبان وأبي الدّرداء وغيرهم، قال السّخاويّ في المقاصد الحسنة (23): وكلّها ضعيفة.","وضعّف الشيخ عبدالرحمن بن يحيى المعلّميّ في تعليقه على الفوائد المجموعة (ص221) حديث ابن عمر، وأبي سعيد، وأبي أمامة، وثوبان، وأنس فراجعه."],"118":["قال الله تعالى: ﴿وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ﴾ [سورة التوبة: 129].","وصف الله تعالى العرش بأنّه مربوب، وكلّ مربوب مخلوق، فالعرش مخلوق.","وقال تعالى: ﴿وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُ عَلَى الْمَاءِ﴾ [سورة هود: 7].","وليس المراد بالماء ماء البحر، بل هو ماءٌ تحت العرش كما شاء الله تعالى. (انظر: فتح الباري 13/411)."],"120":["قال الله تعالى: ﴿وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ﴾ [سورة التوبة: 129].","وقال تعالى: ﴿وَالْمَلَكُ عَلَى أَرْجَائِهَا وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَانِيَةٌ﴾[سورة الحاقة: 17]."],"128":["قال الله تعالى: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ﴾ [سورة الزّمر: 67].","وقال تعالى: ﴿يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ﴾ [سورة إبراهيم: 48].","فهل العرش يدخل فيما يقبض ويطوى ويُبدّل أو لا؟","فيرى شيخ الإسلام ابن تيمية رحمه الله تعالى أنّ من المخلوقات التي لا يعدم ولا يفنى بالكليّة كالجنّة والنّار والعرش وغير ذلك.","وأمّا ما رُوي عن أنس بن مالك مرفوعاً: سبعة لا تموت ولا تفنى ولا تذوق الفناء: النّار وسكانها، واللّوح، والقلم، والكرسي، والعرش. فهو ليس بحديث.","وقد سئل شيخ الإسلام عن حديث أنس بن مالك فأجاب: هذا الخبر بهذا اللفظ ليس من كلام النبي صلى الله عليه وسلم، وإنما هو من كلام بعض العلماء. وقد اتفق سلف الأمة وأئمتها وسائر أهل السنة والجماعة على أن من المخلوقات مالا يعدم ولا يفنى بالكلية، كالجنة والنار، والعرش وغير ذلك. ولم يقل بفناء جميع المخلوقات إلا طائفة من أهل الكلام المبتدعين، كالجهم بن صفوان ومن وافقه من المعتزلة ونحوهم، وهذا قول باطل يخالف كتاب الله، وسنة رسوله، وإجماع سلف الأمة وأئمتها. كما في ذلك من الدلالة على بقاء الجنة وأهلها، وبقاء غير ذلك مما لا تتسع هذه الورقة لذكره. وقد استدل طوائف من أهل الكلام والمتفلسفة على امتناع فناء جميع المخلوقات بأدلة عقلية. والله أعلم.","مجموع الفتاوى (18/307)."],"130":["قال الله تعالى: ﴿وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ﴾[سورة البقرة: 255].","جاء في صفة الكرسي من الأحاديث والآثار ما يلي:","عن ابن عباس، قال: الكرسيّ موضع القدمين، والعرش لا يقدّر أحدٌ قدره.","رواه الحاكم في مستدركه (3116) عن أبي العباس محمد بن أحمد المحبوبيّ، عن محمد بن معاذ، عن أبي عاصم، عن سفيان - وهو الثوريّ، بإسناده، عن ابن عباس موقوفاً، مثله. وقال: صحيح على شرط الشيخين ولم يخرجاه. انتهى.","قلت: هذا الموقوف رواه أيضاً ابن أبي شيبة في صفة العرش (61) من طريق أبي عاصم، عن سفيان، به.","ورُوي أيضاً عن أبي هريرة مرفوعاً، ولا يصح.","رواه ابن مردويه من طريق الحكم بن ظهير الفزاريّ الكوفيّ، وهو متروك، ، عن السّديّ، عن أبيه، عن أبي هريرة. ذكره الحافظ ابن كثير في تفسيره.","وفي الباب عن ابن مسعود.","وكذلك لا يصح ما روي عن عمر بن الخطّاب قال: أتت امرأةٌ إلى رسول الله صلى الله عليه وسلم فقالت: ادعُ اللهَ أن يدخلني الجنّة. قال: فعظَّم الربَّ تبارك وتعالى وقال: إنّ كرسيه وسع السماوات والأرض، وإنّ له أطيطاً كأطيط الرّحل الجديد من ثقله.","رواه البزار - كشف الأستار (39) عن الفضل بن سهل، ثنا يحيى بن أبي بُكير، ثنا إسرائيل، عن أبي إسحاق، عن عبدالله بن خليفة، عن عمر، فذكره.","ورواه ابنُ أبي عاصم في السنة (574)، والضياء المقدسيّ في المختارة (151)، وأبو يعلى الموصليّ في مسنده كما قال ابن كثير في تفسيره كلّهم من طريق يحيى ابن أبي بكير، بإسناده، مثله.","قال البزّار: هذا لا نعلم أحداً رواه من الصحابة رفعه إلا عمر، وقفه الثوريّ على عمر، وعبدالله بن خليفة لم يرو عنه إلاّ أبو إسحاق، وقد رُوي عن جبير بن مطعم بغير لفظه.","وقال الحافظ ابن كثير: وعبدالله بن خليفة، وليس بذاك المشهور، وفي سماعه من عمر نظر، ثم منهم من يرويه عنه، عن عمر موقوفاً، ومنهم من يرويه عنه مرسلاً، ومنهم من يزيد في متنه زيادة غريبة، ومنهم من يحذفها. انتهى.","قلت: وهو كما قال، فقد رواه ابن جرير في تفسيره عن عبدالله بن أبي زياد القطوانيّ، قال: حدّثنا عبيد الله بن موسى، قال: أخبرنا إسرائيل، عن أبي إسحاق، عن عبدالله بن خليفة، قال: أتت امرأة النبيَّ صلى الله عليه وسلم فقالت: ادعُ الله أن يدخلني الجنّة. فعظّم الرّبُّ عزّ وجلّ ثم قال: إنّ كرسيَّه وسع السماوات والأرض وإنّه لينتقد عليه، فما يفضل منه مقدار أربع أصابع. ثم قال بأصابعه فجمعها: وإنّ له أطيطاً كأطيط الرّحل الجديد إذا رُكب من ثقله. فهذا مرسل، وفي متنه زيادة غريبة كما قال ابن كثير وهي منكرة.","وأمّا قول الهيثميّ في المجمع (274): رواه البزّار ورجاله رجال الصّحيح. فهو ليس كما قال، فإنّ عبدالله بن خليفة هو الهمدانيّ ليس من رجال الصحيح، وإنّما روى له ابن ماجه في تفسيره كما رمز له الحافظ في التقريب، ثم هو لم يوثقه أحدٌ، وإنّما ذكره ابن حبان في الثقات (5/28) ولذا قال فيه الحافظ: مقبول. أي إذا توبع ولم أجد له متابعاً فهو ليّن الحديث.","وكذلك لا يصح أيضاً ما رُوي عن أبي ذرّ، أنّ النبيّ صلى الله عليه وسلم قال: يا أبا ذر ما السّماوات عند الكرسيّ إلاّ كحلقة ملقاة بأرض فلاة، وفضل العرش على الكرسي كفضل الفلاة على الحلقة. رواه ابن حبان (361)، وأبو الشيخ في العظمة (259)، والبيهقي في الأسماء والصفات (862)، وأبو نعيم في الحلية (1/166، 167) كلّهم من طريق إبراهيم بن هشام بن يحيى بن يحيى الغسّانيّ، حدثني أبي، عن جدي، عن أبي إدريس الخولانيّ، عن أبي ذر، فذكر الحديث مختصراً ومطوّلاً.","وقد تم تخريجه مطوّلاً في جموع الإيمان بالأنبياء والرسل، باب ما جاء في عدد الأنبياء.","وهذا إسناد ضعيف جداً، فإن إبراهيم بن هشام الغسّانيّ متروك، كذّبه أبو حاتم وأبو زرعة كما نقل عنهما الذهبي في الميزان.","وله إسناد آخر رواه محمد بن عثمان بن أبي شيبة في كتاب العرش (58) من طريق المختار بن غسان العبدي، عن إسماعيل بن مسلم، عن أبي إدريس الخولانيّ، عن أبي ذرّ، فذكره.","وإسماعيل بن مسلم هو المكي ضعيف عند جمهور أهل العلم.","والمختار بن غسان العبدي من رجال ابن ماجه، وهو على شرط ابن حبان، ولكنه لم يذكره في الثقات. وقد روى عنه عدد، ولم يؤثر فيه توثيق أحد، قال فيه الحافظ في التقريب: مقبول. أي إذا توبع وإلا فليّن الحديث.","وله إسناد آخر رواه البيهقيّ في الأسماء والصفات (861) من طريق الحسن بن عرفة العبديّ، ثنا يحيى بن سعيد السعدي البصريّ، ثنا عبدالملك بن جريج، عن عطاء، عن عبيد بن عمير اللّيثيّ، عن أبي ذرّ، فذكر الحديث نحوه.","قال البيهقيّ: تفرّد به يحيى بن سعيد السعديّ، وله شاهد بإسناد أصحّ.","وهو يقصد به إسناد إبراهيم بن هشام بن يحيى بن يحيى الغساني كما سبق، وأنه ليس بأصح من إسناد يحيى بن سعيد السعديّ.","ويحيى بن سعيد السعديّ هذا ذكره العقيليّ في كتابه الضعفاء (4/403) وقال: عن ابن جريج، لا يتابع على حديثه، وليس بمشهور بالنقل. ولعله يقصد هذا الحديث.","وقال ابن حبان في المجروحين (3/129): يروي المقلوبات والملزقات، لا يجوز الاحتجاج به إذا انفرد.","وترجم له ابنُ عدي في الكامل (7/2699) وذكر طرفاً من هذا الحديث وقال: وهذا حديث منكر من هذا الطريق عن ابن جريج، عن عطاء....","وقال أبو نعيم: تفرّد به عن ابن جريج يحيى بن سعيد العبشميّ.","وللحديث طرق أخرى لا يسلم منها من مقال.","والخلاصة: أنه لم يثبتْ شيءٌ مرفوعٌ عن النبيِّ صلى الله عليه وسلم في صفة الكرسي، وما جاء عن بعض السّلف أنّه العلم أو هو العرش نفسه فلا دليل عليه، والصّحيح أنه موضع القدمين وهو الثابت عن حبر هذه الأمة عبدالله بن عباس رضي الله عنهما ولا نعلم له مخالفاً من الصّحابة، وقد تلقّاه جمهور أهل العلم من السلف والخلف بالقبول والتسليم، والله تعالى أعلم.","انظر للمزيد: فتاوى شيخ الإسلام ابن تيمية (5/75)، وشرح الطّحاوية (ص277)."],"132":["قال الله تعالى: ﴿وَمَا جَعَلْنَا أَصْحَابَ النَّارِ إِلَّا مَلَائِكَةً وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً﴾ إلى أن قال: ﴿وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ وَمَا هِيَ إِلَّا ذِكْرَى لِلْبَشَرِ﴾ [سورة المدثر: 31]."],"139":["قال الله تعالى: ﴿إِلَّا تَنْصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا فَأَنْزَلَ اللَّهُ سَكِينَتَهُ عَلَيْهِ وَأَيَّدَهُ بِجُنُودٍ لَمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ الَّذِينَ كَفَرُوا السُّفْلَى وَكَلِمَةُ اللَّهِ هِيَ الْعُلْيَا وَاللَّهُ عَزِيزٌ حَكِيمٌ﴾ [التوبة: ٤٠]","فيه إعلام من الله أصحاب رسول الله صلى الله عليه وسلم بأنكم إذا ما نصرتموه فالله ناصره، ومعينه على عدوّه كما نصره الله.","قوله: ﴿إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا﴾ وهم قريش أخرجوه من وطنه وداره.","وقوله: ﴿ثَانِيَ اثْنَيْنِ﴾ أخرجوا النبي صلى الله عليه وسلم وهو أحد الإثنين، أي: واحد من الإثنين كما تقول العرب: قال ثالثُ ثلاثة أي: أحد الثلاثة، ورابعُ أربعة أي أحد الأربعة.","وهما: رسول الله صلى الله عليه وسلم وأبو بكر، لأنهما كانا قد خرجا هاربَيْنِ من قريش، إذْ همّوا بقتل رسول الله صلى الله عليه وسلم، واختفيا في الغار الذي في الجبل الذي يقال له: ثور.","وقوله: ﴿فَأَنْزَلَ اللَّهُ سَكِينَتَهُ عَلَيْهِ﴾ أي على رسوله صلى الله عليه وسلم.","وقوله: ﴿وَأَيَّدَهُ بِجُنُودٍ لَمْ تَرَوْهَا﴾ أي قوّاه وحفظه من أعدائه بجنود وهم الملائكة لم تروها، فكانوا محافظين من في الغار، والكفار قد قرُبوا منهم إلا أنهم لم يستطيعوا أن يقفوا عليهما."],"140":["1- قال الله تعالى: ﴿إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنَ الْمَلَائِكَةِ مُرْدِفِينَ﴾ [سورة الأنفال: 9]","2- وقال تعالى: ﴿وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنْتُمْ أَذِلَّةٌ فَاتَّقُوا اللَّهَ لَعَلَّكُمْ تَشْكُرُونَ إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَنْ يَكْفِيَكُمْ أَنْ يُمِدَّكُمْ رَبُّكُمْ بِثَلَاثَةِ آلَافٍ مِنَ الْمَلَائِكَةِ مُنْزَلِينَ﴾ [آل عمران: 123 – 124]","3- وقال تعالى: ﴿بَلَى إِنْ تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُمْ مِنْ فَوْرِهِمْ هَذَا يُمْدِدْكُمْ رَبُّكُمْ بِخَمْسَةِ آلَافٍ مِنَ الْمَلَائِكَةِ مُسَوِّمِينَ﴾ [آل عمران: 125]","هذه الآيات كلها نزلت في غزوة بدر، فأوّلُ ما نزلت الملائكة كان عددهم ألفا.","ثم صاروا ثلاثة آلاف.","ثم صاروا خمسة آلاف.","قوله: ﴿وَأَنْتُمْ أَذِلَّةٌ﴾ جمعُ ذليل، أراد به قلة العدد، فكان عدد المسلمين ثلاثمائة وثلاثة عشر رجلا، وعدد المشركين نحو تسعمائة إلى الألف.","قال ابن عباس: لم تقاتل الملائكة في المعركة إلا يوم بدر، وفيما سوى ذلك يشهدون القتال ولا يقاتلون، إنما يكونون عددًا ومددًا.","وقوله: ﴿مِنْ فَوْرِهِمْ﴾ أي من ساعتهم ووقتهم بلا إبطاء."],"142":["قال الله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَمْ تَرَوْهَا وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا﴾[سورة الأحزاب: ٩]","قوله: ﴿جَاءَتْكُمْ جُنُودٌ﴾ أي: الأحزاب من الكفار والمشركين، فأقبل أبو سفيان بقريش ومن معه من الناس، حتى نزلوا بعقْوة رسول الله صلى الله عليه وسلم، واقبل عيينة بن حصن أحد بني بدر ومن تبعه من الناس، حتى نزلوا بعقْوة رسول الله صلى الله عليه وسلم، وكاتب اليهود أنهم يظاهرون أبا سفيان.","وقوله: ﴿فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا﴾ فبعث الله عليهم الرعب والريح، يقال: كلما أوقدوا نارا أطفأناها.","وقوله: ﴿وَجُنُودًا لَمْ تَرَوْهَا﴾ هم الملائكة في أصح أقوال أهل العلم إلا أنهم لم يقاتلوا لأن الله كفى المؤمنين القتال."],"143":["كانت غزوة بني قريظة في السنة الخامسة من الهجرة عقب غزوة الأحزاب، وكان سببه نقض بني قريظة العهد الذي بينهم وبين النبي صلى الله عليه وسلم في وقت غزوة قريش وحلفائه المدينةَ، فأمرَ اللهُ تعالى نبيَّه بالتوجّه إليهم لقتالهم."],"144":["قال الله تعالى: ﴿لَقَدْ نَصَرَكُمُ اللَّهُ فِي مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنْكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُمْ مُدْبِرِينَ ثُمَّ أَنْزَلَ اللَّهُ سَكِينَتَهُ عَلَى رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَنْزَلَ جُنُودًا لَمْ تَرَوْهَا وَعَذَّبَ الَّذِينَ كَفَرُوا وَذَلِكَ جَزَاءُ الْكَافِرِينَ﴾ [التوبة: ٢٥ – ٢٦]","كان عدد المسلمين في هذه الغزوة عشرة آلاف من المهاجرين والأنصار، وألفين من الطلقاء، وكان عدد المشركين أربعة آلاف من هوازن وثقيف.","قال سعيد بن جبير: أمدَّ اللهُ تعالى نبيَّه بخمسة آلاف من الملائكة مسومين.","وفي الخبر: أن رجلا من بني نضر يقال له شجرة، قال للمؤمنين بعد القتال: أين الخيل الُبلْق والرجال الذين عليهم ثياب بيض، ما كنا نراكم فيهم إلا كهيئة الشامة وما كنا قتلنا إلا بأيديهم؟ فأخبروا بذلك النبي صلى الله عليه وسلم فقال: تلك الملائكة. ذكره البغوي في تفسيره."],"156":["قال الله تعالى: ﴿الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ﴾ [غافر: 7]."],"196":["قال الله تعالى: ﴿عَلَّمَهُ شَدِيدُ الْقُوَى ذُو مِرَّةٍ فَاسْتَوَى وَهُوَ بِالْأُفُقِ الْأَعْلَى ثُمَّ دَنَا فَتَدَلَّى فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى فَأَوْحَى إِلَى عَبْدِهِ مَا أَوْحَى مَا كَذَبَ الْفُؤَادُ مَا رَأَى أَفَتُمَارُونَهُ عَلَى مَا يَرَى وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى عِنْدَ سِدْرَةِ الْمُنْتَهَى عِنْدَهَا جَنَّةُ الْمَأْوَى إِذْ يَغْشَى السِّدْرَةَ مَا يَغْشَى مَا زَاغَ الْبَصَرُ وَمَا طَغَى لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى﴾ [سورة النجم: ٥ – ١٨].","فقوله تعالى: ﴿مَا كَذَبَ الْفُؤَادُ مَا رَأَى﴾ يعني جبريل في المرة الأولى في صورته الأصلية، كان له ستمائة جناح وقد سد الأفق.","وقوله تعالى: ﴿لَقَدْ رَآهُ نَزْلَةً أُخْرَى عِنْدَ سِدْرَةِ الْمُنْتَهَى﴾ جبريل في المرة الثانية، وذلك عند الإسراء والمعراج.","ويدل عليه ما روي عن ابْنِ مَسْعُودٍ، أَنَّهُ قَالَ: إِنَّ مُحَمَّداً لَمْ يَرَ جِبْرِيلَ فِي صُورَتِهِ إِلَّا مَرَّتَيْنِ، أَمَّا مَرَّةٌ، فَإِنَّهُ سَأَلَهُ أَنْ يُرِيَهُ نَفْسَهُ فِي صُورَتِهِ، فَأَرَاهُ صُورَتَهُ فَسَدَّ الْأُفُقَ، وَأَمَّا الْأُخْرَى فَإِنَّهُ صَعِدَ مَعَهُ حِينَ صَعِدَ بِهِ، وَقَوْلُهُ: ﴿وَهُوَ بِالْأُفُقِ الْأَعْلَى ثُمَّ دَنَا فَتَدَلَّى فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى فَأَوْحَى إِلَى عَبْدِهِ مَا أَوْحَى﴾ [النجم: ٧ – ١٠]، قَالَ: فَلَمَّا أَحَسَّ جِبْرِيلُ رَبَّهُ، عَادَ فِي صُورَتِهِ وَسَجَدَ، فَقَوْلُهُ: ﴿وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى عِنْدَ سِدْرَةِ الْمُنْتَهَى عِنْدَهَا جَنَّةُ الْمَأْوَى إِذْ يَغْشَى السِّدْرَةَ مَا يَغْشَى مَا زَاغَ الْبَصَرُ وَمَا طَغَى لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى﴾ [النجم: ١٣ – ١٨] قَالَ خَلْقَ جِبْرِيلَ عَلَيْهِ السَّلَام.","رواه الإمام أحمد (3864) فقال: حدثنا أبو النضر، حدثنا محمد بن طلحة، عن الوليد بن قيس، عن إسحاق بن أبي الكهتلة، قال محمد: أظنه عن ابن مسعود، فذكر الحديث.","وإسحاق بن أبي الكهتلة ذكره ابن حبان في الثقات، وروى عنه اثنان، وذكره البخاري في التاريخ الكبير وابن أبي حاتم في الجرح والتعديل، ولم يذكرا فيه جرحا ولا تعديلا، وفيه الشك أيضا في وصله عن ابن مسعود إلا أن هذا التفسير هو المعتمد عند جمهور المفسرين بأن النبي صلى الله عليه وسلم رأى جبريل عليه السلام في صورته الأصلية مرتين، وهو الذي ذكره أيضا ابن أبي حاتم في تفسيره، وعنه ابن كثير.","وقوله: فلما أحس جبريل ربه، أي: ظهر له آثار تجليه.","وقوله: عاد، أي: صار في صورته الأصلية، ولذلك رآه النبي صلى الله عليه وسلم مرة أخرى."],"200":["قال الله تعالى: ﴿فَأَرْسَلْنَا إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا﴾ [سورة مريم: 17].","والرّوح اسمٌ من أسماء جبريل عليه السّلام، مثل قوله تعالى: ﴿تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ﴾ [سورة القدر: 4]. قال ابن عباس: الرّوحُ هو جبريل."],"201":["قال الله تعالى: ﴿نَزَلَ بِهِ الرُّوحُ الْأَمِينُ﴾ [سورة الشّعراء: 193].","وقال تعالى: ﴿قُلْ نَزَّلَهُ رُوحُ الْقُدُسِ مِنْ رَبِّكَ بِالْحَقِّ﴾ [النحل: 102]."],"220":["قال الله تعالى: ﴿مَنْ كَانَ عَدُوًّا لِلَّهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكَالَ فَإِنَّ اللَّهَ عَدُوٌّ لِلْكَافِرِينَ﴾ [سورة البقرة: 98]."],"223":["قال الله تعالى: ﴿بِأَيْدِي سَفَرَةٍ كِرَامٍ بَرَرَةٍ﴾ [سورة عبس: 15، 16]."],"224":["قال الله تعالى: ﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾ [سورة الزّمر: 73]."],"226":["جاء في كتاب الله: ﴿وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُمْ مَاكِثُونَ﴾ [سورة الزخرف: 77]. ومالك هو: خازن جهنّم.","قال تعالى: ﴿عَلَيْهَا تِسْعَةَ عَشَرَ﴾ [سورة المدثر: 30].","لعلّ مالكاً هو رئيسهم أو هو أعظم ولذا خُصّ بالذّكر من بينهم."],"227":["قال الله تعالى: ﴿قُلْ يَتَوَفَّاكُمْ مَلَكُ الْمَوْتِ الَّذِي وُكِّلَ بِكُمْ ثُمَّ إِلَى رَبِّكُمْ تُرْجَعُونَ﴾ [سورة السجدة: 11]."],"228":["قال الله تعالى: ﴿وَكَتَبْنَا لَهُ فِي الْأَلْوَاحِ مِنْ كُلِّ شَيْءٍ مَوْعِظَةً وَتَفْصِيلًا لِكُلِّ شَيْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِأَحْسَنِهَا﴾ [سورة الأعراف: 145].","قال الله تعالى: ﴿إِنَّا أَنْزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا لِلَّذِينَ هَادُوا وَالرَّبَّانِيُّونَ وَالْأَحْبَارُ بِمَا اسْتُحْفِظُوا مِنْ كِتَابِ اللَّهِ وَكَانُوا عَلَيْهِ شُهَدَاءَ﴾ [سورة المائدة: 44]."],"229":["قال الله تعالى: ﴿وَلَمَّا رَجَعَ مُوسَى إِلَى قَوْمِهِ غَضْبَانَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِي مِنْ بَعْدِي أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى الْأَلْوَاحَ﴾ [سورة الأعراف: 150]."],"230":["قال تعالى: ﴿قُلْ فَأْتُوا بِالتَّوْرَاةِ فَاتْلُوهَا إِنْ كُنْتُمْ صَادِقِينَ﴾ [سورة آل عمران: 93]."],"231":["قال الله تعالى: ﴿وَأَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ .....﴾[سورة المائدة: 48]."],"232":["قال الله تعالى: ﴿وَمَا يَأْتِيهِمْ مِنْ ذِكْرٍ مِنَ الرَّحْمَنِ مُحْدَثٍ إِلَّا كَانُوا عَنْهُ مُعْرِضِينَ﴾ [سورة الشعراء: 5].","أخرج البخاريّ بإسنادين موقوفين: أحدهما بإسناده عن عكرمة، عن ابن عباس قال: كيف تسألون أهلَ الكتاب عن كتبهم، وعندكم كتاب الله أقربُ الكتب عهداً بالله، تقرءونه محضاً لم يُشب. أخرجه في كتاب التوحيد (7522).","وقوله: لم يُشَبْ بضم أوّله، وفتح الشين المعجمة، وسكون الموحّدة، أي لم يخالطه غيره.","والثاني: بإسناده عن عبيد الله بن عبدالله، أنّ عبدالله بن عباس، قال: يا معشر المسلمين كيف تسألون أهل الكتاب عن شيء، وكتابكم الذي أنـزل الله على نبيّكم أحدثُ الأخبار بالله محضاً لم يُشب. وقد حدَّثكم الله أن أهل الكتاب قد بدّلوا من كتب الله وغيّروا، فكتبوا بأيديهم قالوا: هو من عند الله ليشتروا بذلك ثمناً قليلاً، أو لا ينهاكم ما جاء من العلم عن مسألتهم، فلا والله ما رأينا رجلاً منهم يسألكم عن الذي أنزل عليكم.","أخرجه البخاري في كتاب الشّهادات (2685)، وفي الاعتصام (7363)، وفي التوحيد (7523).","وكذلك جاء عن كعب الأحبار منسوباً إلى الله سبحانه وتعالى: عليكم بالقرآن فإنّه أحدث الكتب عهداً بالرّحمن.","وفي رواية أخرى عنه: إن الله قال في التوراة: يا موسى، إنّي أنزّل عليك توراة حديثة، أفتح بها أعيناً عمياً، وآذانا صُمّاً، وقلوباً غلفاً.","رواه ابن أبي حاتم بسند حسن، كما قال الحافظ في الفتح (13/499)."],"235":["قال الله تعالى: ﴿إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ [سورة القدر:1].","وقال تعالى: ﴿شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ﴾ [سورة البقرة: 185].","أي أنّه نزل في ليلة القدر من اللّوح المحفوظ إلى السّماء الدّنيا، ثم أنزل على النبيّ صلى الله عليه وسلم على ما أراد الله إنزاله إليه.","جاء ذلك عن ابن عباس من طرق كثيرة، ولم نجد له مخالفاً من أحد من الصّحابة، ومن هذه الطّرق:"],"238":["قال الله تعالى: ﴿نَزَلَ بِهِ الرُّوحُ الْأَمِينُ عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِرِينَ بِلِسَانٍ عَرَبِيٍّ مُبِينٍ﴾ [سورة الشّعراء: 193، 195].","وقال تعالى: ﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ قُرْآنًا عَرَبِيًّا لِتُنْذِرَ أُمَّ الْقُرَى وَمَنْ حَوْلَهَا﴾ [سورة الشورى: 7]."],"242":["قال الله تعالى: ﴿وَرُسُلًا قَدْ قَصَصْنَاهُمْ عَلَيْكَ مِنْ قَبْلُ وَرُسُلًا لَمْ نَقْصُصْهُمْ عَلَيْكَ وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا﴾ [سورة النساء: 164].","وهذه تسمية الأنبياء الذين نُصَّ على أسمائهم في القرآن:","وهم: آدم، وإدريس، ونوح، وهود، وصالح، وإبراهيم، ولوط، وإسماعيل، وإسحاق، ويعقوب، ويوسف، وأيوب، وشعيب، وموسى، وهارون، ويونس، وداود، وسليمان، وإلياس، واليسع، وزكريا، ويحيى، وعيسى، وسيدهم جميعاً محمد ابن عبدالله صلوات الله وسلامه عليهم أجمعين.","وأمّا ذو الكِفل، فقال كثيرٌ من المفسّرين أنّه أيضاً من الأنبياء.","كذا ذكره ابن كثير في تفسيره.","﴿وَرُسُلًا لَمْ نَقْصُصْهُمْ عَلَيْكَ﴾ أي خلقاً آخرين لم يذكروا في القرآن.","واختلف في عدّة الأنبياء والمرسلين، فالصّحيح في هذا الباب أنه لم يثبت فيه حديث في ذكر عدد الأنبياء يعتمد عليه.","وأمّا الأحاديث التي رُويت في هذا الباب، فمنها:","ما رُوي عن أنس بن مالك، قال: سئل النبيّ صلى الله عليه وسلم كم المرسلون؟ فقال: ثلاثمائة وستة عشر، عدّة أصحاب بدر.","رواه تمّام في فوائده (1431) عن أبي الحسن خيثمة بن سليمان، نا أبو عبدالله محمد بن عيسى بن حيان بالمدائن، نا محمد بن الفضل بن عطية، عن زيد العمّي، عن معاوية بن قرّة، عن أنس بن مالك، فذكره.","وفيه محمد بن الفضل بن عطية العبديّ مولاهم الكوفيّ، أهل العلم مطبقون على تضعيفه، بل أكثر أهل العلم كذّبوه.","وشيخه زيد العمي هو: ابن الحواري البصريّ، اسم أبيه: مرّة،وهو ضعيف أيضاً.","ورُوي عنه أيضا مرفوعاً: بعث الله ثمانية آلاف نبي: أربعة آلاف إلى بني إسرائيل، وأربعة آلاف إلى سائر النّاس.","رواه أبو يعلى (1377) عن أحمد بن إسحاق أبي عبدالله الجوهريّ البصريّ، حدّثنا مكّي بن إبراهيم، حدّثنا موسى بن عبيدة الرّبذيّ، عن يزيد الرَّقاشيّ، عن أنس فذكره.","ومن طريقه أورده الحافظ ابنُ كثير في تفسيره وقال: وهذا أيضاً إسناد ضعيف، فيه الرّبذيّ ضعيف، وشيخه الرّقاشي أضعف منه أيضاً انتهى.","والهيثميّ أورده في المجمع (8/210) وأعلّه بموسى بن عبيدة الرّبذيّ فقط، وهو تقصير منه، فإنّ شيخه أضعف منه كما قال الحافظ ابن كثير.","وذكر عنه حديثاً آخر، وعزاه إلى الطبرانيّ في الأوسط، وفيه إبراهيم بن مهاجر بن مسمار وهو ضعيف.","ورُوي عنه أيضاً مرفوعاً: كان فيمن خلا من إخواني من الأنبياء ثمانية آلاف نبي، ثم كان عيسى بن مريم، ثم كنتُ أنا.","رواه أبو يعلى (1337) عن أبي الرّبيع الزّهرانيّ، حدّثنا محمد بن ثابت العبديّ، حدّثنا معبدبن خالد الأنصاريّ، عن يزيد الرّقاشيّ، عن أنس بن مالك، فذكره.","وأورده الهيثميّ في المجمع (8/211) وأعلّه بمحمد بن ثابت العبديّ وقال: وهو ضعيف.","وفيه معبدبن خالد الأنصاريّ مجهول، ويزيد الرّقاشي أضعف من الجميع.","وذكره الحافظ ابن كثير عنه من وجه آخر ولفظه: بُعثْتُ على إثر من ثمانية آلاف نبي من بني إسرائيل. وقال: وهذا غريب من هذا الوجه، وإسناده لا بأس به، ورجاله كلّهم معروفون إلاّ أحمد بن طارق هذا، فإني لا أعرفه بعدالة ولا جرح. انتهى.","وفي الباب أيضاً عن أبي ذرّ في حديث طويل، وفيه أنّه سأل النّبيّ صلى الله عليه وسلم عن أشياء منها قوله: قلت: يا رسول الله، كم الأنبياء؟ قال: مائة ألف وعشرون ألفاً. قلت: يا رسول الله: كم الرّسل من ذلك؟ قال: ثلاثمائة وثلاثة عشر جمّاً غفيراً.","وإليكم الحديث بطوله، ولبعض فِقْراته شواهد صحيحة.","عن أبي ذر، قال: دخلتُ المسجدَ، فإذا رسول الله صلى الله عليه وسلم جالس وحده. قال: يا أبا ذرّ إنّ للمسجد تحيَّةً، وإنّ تحيتَه ركعتان فقُمْ فاركعْهُمَا. قال: فقُمتُ فركعتهما، ثم عُدْتُ فجلستُ إليه، فقلت: يا رسول الله إنّك أمرتني بالصّلاة فما الصّلاة؟ قال: خير موضوع، استَكْثِرْ أو اسْتَقِلَّ. قال: قلت: يا رسول الله، أيُّ العمل أفضل؟ قال: إيمان بالله، وجهاد في سبيل الله. قال: قلت: يا رسول الله، فأيُّ المؤمنين أكمل إيماناً؟ قال: أحسنهم خُلُقًا. قلت: يا رسول الله، فأيُّ المؤمنين أَسْلم؟ قال: مَنْ سَلِم النَّاسُ من لسانه ويده. قال: قلت: يا رسول الله، فأيُّ الصّلاة أفضل؟ قال: طُول القنوت. قال: قلت: يا رسول الله، فأيُّ الهجرة أفضل؟ قال: مَنْ هجر السِّيئات. قال: قلت: يا رسول الله، فما الصّيام؟ قال: فَرْضٌ مُجْزِىءٌ، وعند الله أضعافٌ كثيرةٌ. قال: قلت: يا رسول الله، فأيُّ الجهاد أفضل؟ قال: مَنْ عُقِرَ جَوادُه، وأُهْريقَ دَمُه. قال: قلت: يا رسول الله، فأيُّ الصّدقة أفضل؟ قال: جَهْدُ المُقِلِّ يُسَرُّ إلى فَقِيرٍ. قلت: يا رسول الله، فأيُّ ما أَنْزلَ اللهُ عليك أَعْظَمُ؟ قال: آيةُ الكُرْسِي. ثم قال: يا أبا ذر، ما السّماواتُ السّبعُ مع الكرسي إلاّ كَحَلْقَةٍ مُلْقَاةٍ بأرض فَلاة، وفَضْلُ العرش على الكرسي كفضل الفَلاة على الحَلْقة. قال: قلت: يا رسول الله، كم الأنبياء؟ قال: مائةُ ألْفٍ وعشرون ألفاً. قلت: يا رسول الله كم الرّسل من ذلك؟ قال: ثلاثُمائة وثلاثةَ عَشَرَ جَمّاً غَفِيراً. قال: قلت: يا رسول الله، من كان أَوّلُهم؟ قال: آدم. قلت: يا رسول الله، أَنَبيٌّ مُرسل؟ قال: نعم، خلقه الله بيده ونفخ فيه من روحه وكلَّمَه قِبَلاً. ثم قال: يا أبا ذر، أربعةٌ سُرْيانِيون: آدمُ، وشِيثُ، وأَخْنُوخُ، وهو إدريس، وهو أول من خط بالقلم، ، ونُوحٌ. وأربعةٌ من العرب: هودٌ، وشُعيبٌ، وصَالِحٌ، ونَبيُّك محمّد صلى الله عليه وسلم. قلت: يا رسول، الله كم كتاباً أنزله الله؟ قال: مائةُ كتابٍ وأربعةُ كُتُب، أُنزلَ على شِيث خمسون صَحيفةً، وأُنْزِلَ على أُخْنوخَ ثلاثون صَحيفةً، وأُنزلَ على إبراهيم عَشْرُ صَحائف، وأُنزل على موسى قَبْل التّوراة عَشْرُ صحائفَ، وأُنْزل التَّوراةُ، والإنجيلُ، والزّبور، والقرآن. قال: قلت: يا رسول الله، ما كانتْ صحيفةُ إبراهيم؟ قال: كانت أمثالاً كلُّها: أَيُّها الملك المسَلَّطُ المبتلى المغرورُ، إنّي لم أَبْعَثْك لتجمع الدّنيا بعضها على بعض، ولكني بعَثْتُك لترد عنّي دعوةَ المظلوم، فإني لا أَرُدُّها ولو كانت من كافر، وعلى العَاقِل ما لم يكن مغلوباً على عقله أن تكونَ له ساعاتٌ: ساعةٌ يناجي فيها ربَّه، وساعة يحاسب فيها نفسَه، وساعةٌ يتَفَكَّرُ فيها في صُنع الله، وساعةٌ يخلو فيها لحاجته من المطعم والمشرب. وعلى العاقل أن لا يكونَ ظَاعِناً إلاّ لثلاثٍ: تَزَوُّد لِمَعَادٍ، أو مَرَمَّةٍ لِمَعاش، أو لََذَّةٍ في غير مُحَرَّم. وعلى العاقل أن يكونً بصيراً بزمانه، مُقبلاً على شَأنِه، حافظا للسانه، ومَنْ حَسَبَ كَلامَهُ مِنْ عَمَلِه قَلَّ كَلامُه إلاَّ فيما يَعْنِيه. قلتُ: يا رسول الله، فما كانتْ صُحُف موسى؟ قال: كانتْ عِبَراً كُلُّها: عَجِبْتُ لمن أيقن بالموت ثم هو يفرح، وعجبت لمن أيقن بالنار ثم هو يضحك، وعجبت لمن أيقن بالقدر ثم هو يَنْصِبُ، عجبت لمن رأى الدّنيا وتقلبها بأهلها ثم اطمأن إليها، وعجبت لمن أيقن بالحساب غداً ثم لا يعمل. قلت: يا رسول الله، أَوْصِني. قال: أوصيك بتقوى الله، فإنّه رأس الأمر كلُّه. قلت: يا رسول الله، زِدْني. قال: عليك بتلاوة القرآن، وذكر الله فإنّه نُورٌ لك في الأرض، وذُخْرٌ لك في السّماء. قلت: يا رسول الله، زِدْني. قال: إيَّاك وكثرَة الضَّحِك، فإنه يُميتُ القلب، ويَذْهبُ بنور الوجه. قلت: يا رسول الله زِدْني. قال: عليك بالصَّمت إلاّ من خير، فإنّه مطردةٌ للشّيطان عنك، وعونٌ لك على أمر دينك. قلت: يا رسول الله زدْني. قال: عليك بالجهاد فإنّه رَهْبانيةُ أُمَّتِي. قلت: يا رسول الله، زدني. قال: أَحِبَّ المساكين وجَالِسْهم. قلت: يا رسول الله زدني. قال: انظر إلى من تحتك ولا تنظر إلى من فوقك، فإنّه أجدر أن لا تُزْدَرَى نِعْمةُ الله عندك. قلت: يا رسول الله، زِدْني. قال: قلْ الحقَّ وإِنْ كان مُرّاً. قلت: يا رسول الله، زدني. قال: لِيِرُدَّكَ عن النّاس ما تَعرفُ مِنْ نفسك، ولا تجد عليهم فيما تأتي، وكفى بك عَيْباً أن تعرف من الناس ما تجهل من نفسك، أو تجدَ عليهم فيما تأتي. ثم ضرب بيده على صدري فقال: يا أبا ذر لا عَقْل كالتَّدْبِير، وَلا وَرَعَ كالكَفِّ، ولا حَسَبَ كحُسْن الخُلُقِ.","إسناده ضعيف جدّاً. رواه ابن حبان في صحيحه (361)، وأبو نعيم في الحلية (1/166)، والطبراني في الكبير (2/167)، والآجري، كما ذكره ابن كثير في تفسيره (2/472)، ، كلّهم من طرق عن إبراهيم بن هشام بن يحيى بن يحيى الغسّانيّ، قال: حدّثني أبي، عن جدّي، عن أبي إدريس الخولانيّ، عن أبي ذرّ، فذكر الحديث بطوله، واللّفظ لابن حبان.","ذكره ابن كثير في تفسيره في سورة النساء (آية: 164) عن ابن مردويه بهذا الإسناد أيضاً وزاد فيه بعد قوله: ونبيك محمد صلى الله عليه وسلم. وأوّل نبي من أنبياء بني إسرائيل: موسى، وآخرهم عيسى. وأوّل النّبيين آدم، وآخرهم نبيّك.","وقال: روى هذا الحديث بطوله أبو حاتم بن حبان البُستيّ في كتابه، وقد وَسَمه بالصِّحة، وخالفه أبو الفرج بن الجوزيّ، فذكر هذا الحديث في كتابه الموضوعات، واتّهم به إبراهيم بن هشام، ولا شك أنه قد تَكلّم فيه غير واحد من أئمّة الجرح والتعديل من أجل هذا الحديث. انتهى.","وإبراهيم بن هشام بن يحيى بن يحيى الغسّانيّ، قال فيه أبو حاتم: قلت لأبي زرعة: لا تحدّث عن إبراهيم بن هشام بن يحيى، فإنّي ذهبتُ إلى قريته فذكر حكاية وقال: وأظنّه لم يطلب العلم وهو كذّاب.","قال عبدالرحمن بن أبي حاتم: ذكرتُ لعلي بن الحسين بن الجنيد بعض هذا الكلام عن أبي، فقال: صدق أبو حاتم، ينبغي أن لا يُحدَّث عنه. انتهى الجرح والتعديل (2/143).","قال الهيثميّ في المجمع (4/216): فيه إبراهيم بن هشام بن يحيى الغسّانيّ، وثّقه ابنُ حبان، وضعّفه أبو حاتم وأبو زرعة.","وقال الذّهبي في الميزان (1/72، 73): هو صاحب حديث أبي ذرّ الطّويل، انفرد به عن أبيه، عن جدّه. ونقل قول أبي حاتم بأنّه كذّاب، كما نقل أيضاً عن ابن الجوزيّ أنه قال: قال أبو زرعة: كذّاب.","كما نقل عن الطبرانيّ قوله: لم يرو هذا عن يحيى إلاّ ولده وهم ثقات. وذكره ابن حبان في الثقات (8/79)، وأخرج حديثه في الأنواع.","وقال في موضع آخر من الميزان (4/378): إبراهيم بن هشام أحد المتروكين الذين مشّاهم ابنُ حبان فلم يُصبْ.","قلت: وفي قوله هذا دليلٌ واضح على تساهل ابن حبان، وإدخاله الضعفاء والمجاهيل في كتابه الثقات وإخراج أحاديثهم في صحيحه فتنبّه إلى ذلك!.","والحافظ ابن حجر هو الآخر أيضاً من تساهل، فنقل تصحيح ابن حبان ولم يتعقبه عليه، بل عضّده بقول مجاهد، أخرجه سعيد بن منصور في تفسيره بسند صحيح عنه. انظر: الفتح (13/411).","ورواه الإمام أحمد (21546) عن وكيع، حدّثنا المسعوديّ، أنبأني أبو عمر الدّمشقيّ، عن عبيد بن الخشخاش، عن أبي ذرّ، قال (فذكر قطعاً من الحديث).","والمسعوديّ هو عبدالرحمن بن عبدالله. ومن طريقه أخرجه النسائيّ (8/275) ما يتعلّق بتعوّذ من شرّ شياطين الجنّ والإنس فقط.","وإسناده ضعيف أيضاً، عبيد بن الخشخاش قال فيه البخاريّ: لم يذكر سماعاً من أبي ذرّ. وضعّفه الدّارقطني، وفي التقريب: ليّن.","وأبو عمر، ويقال: أبو عمرو الدّمشقيّ، قال الدّارقطنيّ: متروك. كما في اللّسان (7/87). والمسعوديّ هو عبدالرحمن بن عبدالله بن عتبة وهو إن كان صدوقاً إلاّ أنه اختلط قبل موته.","وكذلك لا يصح ما رواه الحاكم (2/597) من طريق يحيى بن سعيد السّعديّ البصريّ، ثنا عبدالملك بن جريج، عن عطاء، عن عبيد بن عمير اللّيثيّ، عن أبي ذرّ، فذكر فيه بعض الجمل من الحديث. ومن طريقه رواه البيهقيّ في السنن (9/4) وقال: تفرّد به يحيى بن سعيد السّعديّ.","وقال الذهبيّ في تلخيص المستدرك: السّعديّ ليس بثقة.","وللحديث أسانيد أخرى ولم يسلم منها شيء.","وفي الباب أيضاً ما رُوي عن أبي أمامة قال: كان رسول الله صلى الله عليه وسلم في المسجد جالساً وكانوا يظنون أنّه ينزل عليه فاقصروا عنه، حتى جاء أبو ذرّ فاقتحم فأتى فجلس إليه فأقبل عليه النّبيُّ صلى الله عليه وسلم فقال: يا أبا ذر، هلْ صليتَ اليوم؟. قال: لا قال: قُمْ فَصلِّ. فلمّا صلّى أربع ركعات الضُّحى أقبل عليه، فقال: يا أبا ذر، تعوَّذْ منْ شَرِّ شياطين الجنّ والأنس. قال: يا نبي الله، وهل للإنس شياطين؟ قال: نعم شياطين الإنس والجن يوحى بعضُهم إلى بعض زخرف القول غروراً. ثم قال: يا أبا ذر، ألا أُعلّمُكَ كلمةً من كنز الجنّة؟. قال: بلى جعلني الله فداءك. قال: قُلْ لا حولَ ولا قوَّة إلاّ بالله. قال: فقلت: لا حول ولا قوّة إلا بالله. قال: ثم سكت عنّى فاستبطأتُ كلامَه، قال: قلتُ: يا نبي الله، إنّا كنّا أهل جاهليّة وعبادة أوثان فبعثك الله رحمة للعالمين، أرأيت الصلاة ماذا هي؟ قال: خيرٌ موضوعٌ من شاء استقَلَّ ومن شاء اسْتَكْثَر. قال: قلت: يا نبي الله، أرأيتَ الصِّيام ماذا هو؟ قال: فَرْضٌ مُجْزئٌ. قال: قلت: يا نبي الله، أرأيتَ الصَّدقة ماذا؟ قال: أضعاف مضاعفة، وعند الله المزيد. قال: قلت: يا نبي الله، فأيُّ الصّدقة أفضل؟ قال: سِرٌّ إلى فقير، وجُهْدٌ مِنْ مُقِلٍّ. قال: قلت: يا نبي الله، أيُّما أُنزل عليك أعظم؟ قال: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾ [ آيه الكرسي]. قال: قلتُ: يا نبي الله أيُّ الشّهداء أفضل؟ قال: من سُفك دَمُه وعُقِر جَوادُه. قال: قلت: يا نبي الله، فأيُّ الرِّقاب أفضل؟ قال: أغلاها ثمناً، وأنفسها عند أهلها. قال: قلت: يا نبي الله، فأيُّ الأنبياء كان أَولَّ؟ قال: آدم عليه السّلام. قال: قلتُ: يا نبي الله أو نبيٌّ كان آدم؟ قال: نعم نبيٌّ مُكلَّم، خلقه الله بيده، ثم نفخ فيه رُوحَه، ثم قال له: يا آدمُ قُبلاً. قال: قلتُ: يا رسول الله كم وَفَى عِدَّةُ الأنبياء؟ قال: مائةُ ألف وأربعةٌ وعشرون ألفاً، الرّسلُ من ذلك ثلاثُمائة وخمسةَ عَشَر جماً غفيراً.","رواه أحمد (22288)، والطّبراني في الكبير (7871) كلاهما من حديث أبي المغيرة، حدّثنا مُعان بن رفاعة، حدّثني علي بن يزيد، عن القاسم أبي عبدالرحمن، عن أبي أمامة.","وفيه سلسلة من الضّعفاء: فمعان بن رفاعة السلاميّ وشيخه: علي بن يزيد، وهو ابن أبي زياد الألهاني، ، وشيخه القاسم أبو عبدالرحمن كلّهم متكلّم فيهم، وبهم أعلّه الحافظ ابن كثير في تفسيره في سورة النساء (آية: 164).","وأمّا الهيثميّ فأورده في المجمع (1/159) وأعلَّه بعلي بن يزيد وحده فقال: مداره عليه وهو تقصير منه.","والقاسم هو: ابن عبدالرحمن الدّمشقيّ أبو عبدالرحمن صاحب أبي أمامة.","قال ابن حبان: يروي عن الصّحابة المعضلات، ولكن وثّقه ابن معين، والعجليّ، وقال أبو حاتم: حديث الثقات عنه مستقيم لا بأس به.","قلت: هنا يروي عنه علي بن زيد وهو هالك، وقد سبق أنّ أبا ذرّ، روى هذا الحديث، أو بعضه بنفسه.","وفي الباب أيضاً عن أبي الودّاك قال: قال لي أبو سعيد: هل يُقِرُّ الخوارج بالدّجّال؟ فقلتُ: لا، فقال: قال رسول الله صلى الله عليه وسلم: إنّي خاتمُ ألْف نبيٍّ أو أكْثر، ما بُعث نبيٌّ يُتّبع إلا قد حذَّر أمَّته الدّجال، وإنّي قد بيَّن لي من أمره ما لم يُبيّن لأحد، وإنّه أعور، وإنّ ربَّكم ليس بأعور، وعينُه اليُمنى عوراءُ جاحظةٌ ولا تخفى، كأنّها نُخامةٌ في حائط فجُصّص، وعينُه اليُسرى كأنّها نُخامة في حائطٍ فجصّص، وعينُه اليُسْرى كأنّها كوكب دُرّي معه من كلّ لسانٍ، ومعه صورةُ الجنّة خضراءُ، يجري فيها الماء، وصور النار سوداءُ تدخنُ.","رواه عبدالله بن الإمام أحمد في مسند أبيه (11752) قال: وحدث هذا الحديث في كتاب أبي بخطّ يده: حدّثنا عبدالمتعال بن عبدالوهّاب، حدّثنا يحيى بن سعيد الأمويّ، حدّثنا مجالد، عن أبي الوداك. فذكر مثله.","وأخرجه الحاكم (2/597) من طريق مجالد، وسكت عليه.","ولكن قال الذهبيّ: مجالد ضعيف.","وأورده الهيثميّ في المجمع (7/347) وقال: رواه أحمد وفيه مجالد بن سعيد وثّقه النسائيّ في رواية، وقال في أخرى ليس بالقوي، وضعّفه جماعة.","قلت: مجالد هو: ابن سعيد بن عمر الهمْداني ضعّفه أكثر أهل العلم، وقال فيه البخاريّ: صدوق.","وقد رُوي من حديث جابر بن عبدالله قال: قال رسول الله صلى الله عليه وسلم: إنّي لخاتم ألف نبيّ أو أكثر، وإنّه ليس منهم نبيٌّ إلاّ وقد أنذر قومه الدّجال، وإنّه قد تبيّن لي ما لم يتبيّن لأحد منهم، وإنه أعور، وإنّ ربَّكم ليس بأعور.","رواه البزار - كشف الأستار (3380)، ، عن عمرو بن علي، ثنا يحيى بن سعيد، ثنا مجالد، عن الشّعبيّ، عن جابر، فذكر مثله.","قال الهيثميّ في المجمع (7/347): رواه البزّار، وفيه مجالد بن سعيد، وقد ضعّفه الجمهور، وفيه توثيق.","قلت: مجالد هذا تغيّر في آخر عمره، ولعلّه لم يضبط اسم الصّحابيّ فمرّة رواه عن أبي سعيد، وأخرى عن جابر بن عبدالله مع ضعف فيه.","والخلاصة: ليس في عدد الأنبياء والرّسل حديث صحيح، قال سماحة الشيخ ابن باز رحمه الله بعد أن ذكر عدة أحاديث منها: حديث أبي ذر وغيره: والمقصود أنه ليس في عدد الأنبياء والرسل خبر يُعتمد عليه. انظر: مجموع فتاواه (2/66، 67) (3/30)."],"252":["قال الله تعالى: ﴿قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى وَمَا أُوتِيَ النَّبِيُّونَ مِنْ رَبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ﴾ [سورة البقرة: 136].","الأنبياء عليهم الصّلاة والسّلام معصومون فيما يخبرون عن الله سبحانه وتعالى، وفي تبليغ رسالاته باتفاق الأمّة، ولهذا وجب الإيمان بكل ما أتوه.","وقال تعالى: ﴿آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ﴾ [سورة البقرة: 285].","والأنبياء معصومون من الإقرار على المعصية، وإن وقع منهم ذلك سارعوا إلى التوبة ولا يؤخِّرونها، ولذلك لم يذكر في القرآن شيئاً من ذلك عن نبيٍّ من الأنبياء إلاّ مقروناً بالتوبة والاستغفار، كقول آدم وزوجته: ﴿قَالَا رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ﴾ [سورة الأعراف: 23]، وقول نوح: ﴿قَالَ رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُنْ مِنَ الْخَاسِرِينَ﴾ [سورة هود: 47]، وقول الخليل عليه السّلام: ﴿وَالَّذِي أَطْمَعُ أَنْ يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ﴾ [سورة الشعراء: 82]، وقول موسى: ﴿قَالَ رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي فَغَفَرَ لَهُ﴾ [سورة القصص: 16]، وقوله: ﴿فَلَمَّا أَفَاقَ قَالَ سُبْحَانَكَ تُبْتُ إِلَيْكَ وَأَنَا أَوَّلُ الْمُؤْمِنِينَ﴾ [سورة الأعراف: 143]، وقوله تعالى عن داود: ﴿وَظَنَّ دَاوُودُ أَنَّمَا فَتَنَّاهُ فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ ۩﴾ [سورة ص: 24]، وقوله تعالى عن سليمان ﴿رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي إِنَّكَ أَنْتَ الْوَهَّابُ﴾ [سورة ص: 35]."],"253":["قال الله تعالى: ﴿يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللَّهِ إِلَّا الْحَقَّ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللَّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ فَآمِنُوا بِاللَّهِ وَرُسُلِهِ وَلَا تَقُولُوا ثَلَاثَةٌ انْتَهُوا خَيْرًا لَكُمْ إِنَّمَا اللَّهُ إِلَهٌ وَاحِدٌ سُبْحَانَهُ أَنْ يَكُونَ لَهُ وَلَدٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا﴾ [سورة النساء: 171].","قوله تعالى: ﴿وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ﴾ أي إنّما هو عبد من عباد الله، وخلق من خلْقه قال له: كن، فكان، ورسول من رسله."],"259":["قال الله تعالى: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا﴾ [سورة سبأ: 28].","وقال الله تعالى: ﴿قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا﴾ [سورة الأعراف: 158].","وقال: ﴿يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمْ بُرْهَانٌ مِنْ رَبِّكُمْ وَأَنْزَلْنَا إِلَيْكُمْ نُورًا مُبِينًا﴾ [سورة النساء: 174]. وغيرها من الآيات وهي كثيرة جداً."],"260":["قال الله تعالى: ﴿وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنْصِتُوا فَلَمَّا قُضِيَ وَلَّوْا إِلَى قَوْمِهِمْ مُنْذِرِينَ قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنْزِلَ مِنْ بَعْدِ مُوسَى مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَى طَرِيقٍ مُسْتَقِيمٍ يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللَّهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُجِرْكُمْ مِنْ عَذَابٍ أَلِيمٍ﴾ [سورة الأحقاف: 29، 31].","وقال تعالى: ﴿قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِنَ الْجِنِّ فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا﴾[سورة الجن: 1].","وقال تعالى: ﴿يَا مَعْشَرَ الْجِنِّ وَالْإِنْسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي وَيُنْذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَذَا قَالُوا شَهِدْنَا عَلَى أَنْفُسِنَا وَغَرَّتْهُمُ الْحَيَاةُ الدُّنْيَا وَشَهِدُوا عَلَى أَنْفُسِهِمْ أَنَّهُمْ كَانُوا كَافِرِينَ﴾ [سورة الأنعام:130]."],"267":["قال الله تعالى: ﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ وَكَانَ اللَّهُ بِكُلِّ شَيْءٍ عَلِيمًا﴾ [سورة الأحزاب: 40]."],"272":["قال الله تعالى: ﴿سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾ [سورة الإسراء: ١].","قال الزهري: أسري برسول الله صلى الله عليه وسلم إلى بيت المقدس قبل خروجه إلى المدينة بسنة، هكذا ذكر موسى بن عقبة عن ابن شهاب، وهو قول عروة أيضا، الدلائل للبيهقي (2/354، 355).","هذا هو الصحيح، ومنهم من حدد أنه ليلة سبع وعشرين من ربيع الأول قبل الهجرة، وكان الإسراء والمعراج في ليلة واحدة ومرة واحدة، بالروح والجسد، يقظة لا مناما، على رأي جمهور العلماء.","قال القرطبي: وعليه يدلّ ظاهرُ الكتاب وصحيحُ الأخبار، ومبادرةُ قريش لإنكار ذلك وتكذيبه. ولو كان منامًا، لما أنكروه ولما افتُتِنَ به من افتُتِنَ، إذ كثيرًا ما يُرى في المنام أمورٌ عجيبةٌ وأحوالٌ هائلة، فلا يُستبعَد ذلك في النوم، وإنّما يُستبعَد في اليقظة. المفهم (1/385)."],"274":["قال الله تعالى: ﴿قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ يُوحَى إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾ [سورة الكهف: 110]","وقال تعالى: ﴿وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَ أَفَإِنْ مِتَّ فَهُمُ الْخَالِدُونَ﴾ [سورة الأنبياء: 34].","وقال تعالى: ﴿وَقَالُوا مَالِ هَذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْشِي فِي الْأَسْوَاقِ﴾ [سورة الفرقان: 7].","وقد ورد في الصحيحين مرفوعًا: ﴿إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ﴾ أَنْسَى كَمَا تَنْسَوْنَ، فَإِذَا نَسِيتُ فَذَكِّرُونِي.","رواه البخاريّ في الصلاة (401)، ومسلم في المساجد (572) كلاهما عن عثمان، قال: حدثنا جرير، عن منصور، عن إبراهيم، عن علقمة، قال: قال عبدالله بن مسعود، فذكره في حديث طويل، سيذكر في موضعه."],"277":["قال الله تعالى: ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ مِنْ قَبْلِهِ هُمْ بِهِ يُؤْمِنُونَ وَإِذَا يُتْلَى عَلَيْهِمْ قَالُوا آمَنَّا بِهِ إِنَّهُ الْحَقُّ مِنْ رَبِّنَا إِنَّا كُنَّا مِنْ قَبْلِهِ مُسْلِمِينَ أُولَئِكَ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ بِمَا صَبَرُوا وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ﴾ [سورة القصص: 52، 54].","نزلت هذه الآية في طائفة آمنوا بالنّبيّ صلى الله عليه وسلم كعبدالله بن السّلام من اليهود، وسلمان الفارسيّ من النّصارى."],"281":["قال الله تعالى: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ [سورة الكوثر: 1]."],"289":["إنّ الله تبارك وتعالى وعد نبيَّه صلى الله عليه وسلم بهذا المقام في قوله عزّ وجلّ: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ [سورة الإسراء: 79].","قال أهل العلم: عسى من الله واجب، لا على الشّك والارتياب."],"290":["رُوي عن عبدالله بن سلام قال: إذا كان يوم القيامة جيء بنبيِّكم صلى الله عليه وسلم فأُقْعِد بين يدي الله تبارك وتعالى على كرسيه. فقال رجلٌ لأبي مسعود، يعني الجريريّ ،: إذا كان على كرسيّه فهو معه! قال: ويلكم هذا أقرُّ حديثٍ في الدُّنيا لعيني.","وإسناده ضعيف، رواه ابن أبي عاصم في السنة (786)، والخلال في السنة (237)، والآجرّي في الشّريعة (1097)، وابن جرير في تفسيره كلّهم من طريق يحيى بن كثير أبي غسان العنبريّ، ثنا سلْم بن جعفر، عن سعيد الجريريّ، ثنا سيف السّدوسيّ، عن عبدالله بن سلام، فذكره. وفيه رجال لا يعرفون.","قال الذهبيّ في العلو (203): هذا موقوف ولا يثبت إسناده.","ولكن قال الحاكم بعد أن رواه (8698) من وجه آخر في حديث طويل، عن عبدالله بن سلام وفيه: فيلقى له كرسي عن يمين الله عزّ وجلّ: صحيح الإسناد ولم يخرجاه، وليس بموقوف، فإنّ عبدالله بن سلام على تقدّمه في معرفة قديمة من جملة الصحابة. وقد أسنده بذكر رسول الله صلى الله عليه وسلم في غير موضع.","كذا قال، والصحيح عكسه.","وكذلك لا يصح ما رُوي عن ابن مسعود قال: بينا أنا عند النّبيّ صلى الله عليه وسلم أقرأُ عليه حتّى بلغتُ: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ [سورة الإسراء: 79]. قال: يُجلسني على العرش.","أورده الذّهبيّ في العلو (202) من حديث سلمة الأحمر، عن أشعث بن طُليق، عن عبدالله بن مسعود، فذكره.","قال الذّهبيّ: هذا حديث منكر، لا يُفرح به، سلمة هذا متروك الحديث، وأشعث لم يلق ابنَ مسعود.","قلت: سلمة هو ابن صالح الأحمر الجعفيّ الكوفيّ، ضعّفه أئمّة النّقد.","وكذلك لا يصح أيضاً عن ابن عباس مرفوعاً ولا موقوفاً.","روى الذّهبيّ في العلو (329) فقال: أخبرنا الحسن بن علي، أنا جعفر، أنا السِّلفيّ، أنا علي بن بيان، أنا بشرى الفاتني، أنا عمر بن سَبَنْك القاضيّ، ثنا الحرّ بن محمد بن إشكاب، ثنا عمر بن مدرك الرّازيّ، ثنا مكيّ بن إبراهيم، عن جويبر، عن الضّحاك، عن ابن عباس في قوله: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ قال: يُقعده على العرش.","قال الذّهبيُّ: إسناده ساقط، وعمر هذا الرّازيّ متروك، وفيه جويبر، هكذا قال وسكت عن الحكم عليه، وهو متروك أيضاً كما قاله النسائيّ والدّارقطنيّ بأنه متروك.","ثم قال الذهبيّ: هذا مشهور من قول مجاهد، ورُوي مرفوعاً وهو باطل.","قلت: وقد رُوي عن مجاهد من عدّة طرق: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ قال: يجلسُه معه على عرشه.","أخرجه الآجريّ في الشّريعة (4/1614، 1617)، والخلاّل في السنة (1/212، 213)، وابن جرير في تفسيره.","وأسانيدها كلّها ضعيفة أو منقطعة، وليس فيها شيء من المرفوع أصلاً.","قال القرطبيّ في التذكرة (2/605) بعد أن ذكر قول مجاهد: هذا قول مرغوب عنه، وإن صحَّ فيتأول على أنّه يجلسه مع أنبيائه وملائكته.","وقال ابن عبدالبرّ في التمهيد (7/175) بعد أن نقل قول مجاهد في قوله تعالى: ﴿وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ﴾ [سورة القيامة: 22] قال: تنتظر الثّواب، وليس من النّظر: مجاهد وإن كان أحد المقدّمين في العلم بتأويل القرآن فإنّ له قولين في تأويل آيتين هما مهجوران عند العلماء مرغوب عنهما. أحدهما هذا، والآخر في قول الله عزّ وجلّ: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ قال: يوسّع له العرش فيجلسه معه. وهذا قول مخالف للجماعة من الصّحابة، ومن بعدهم، فالذي عليه العلماء في تأويل هذه الآية أنّ المقام المحمود: الشّفاعة. والكلام في هذه المسألة من جهة النظر يطول. انتهى.","وقال الحافظ الذهبيّ في العلو (2/1081): أمّا قضية قعود النبيّ صلى الله عليه وسلم على العرش فلم يثبت في ذلك نصّ، بل في الباب حديث واه. وما فسَّر به مجاهد للآية كما ذكرنا فقد أنكره بعض أهل الكلام، فقام المروزيّ وقعد، وبالغ في الانتصار لذلك، وجمع كتاباً، وطرق قول مجاهد.","قال: فممن أفتى في ذلك العصر بأنّ هذا الأثر يُسلَّم ولا يعارَض أبو داود السّجستانيّ صاحب السنن، وإبراهيم بن الحربي وخلق، بحيث إن ابن الإمام أحمد قال عقيب قول مجاهد: أنا منكر على كلّ من ردّ هذا الحديث، وهو عندي رجل سوء متهم، سمعتُه من جماعة، وما رأيت محدِّثا ينكره، وعندنا إنما تُنكره الجهميّة.","ثم قال: إنّ الفقيه أبا بكر أحمد بن سلمان النّجاد المحدّث قال: فيما نقله عنه القاضي أبو يعلى الفراء: لو أنّ حالفاً حلف بالطّلاق ثلاثاً: إنّ الله يقعد محمّداً على العرش، واستفتاني لقلت له: صدقت وبررت.","وعلّق عليه الذهبي قائلاً: فأبصر، حفظك الله من الهوى، كيف آل الغلو بهذا المحدّث إلى وجوب الأخذ بأثر منكر، واليوم فيردون الأحاديث الصّريحة في العلو، يحاول بعض الطغام أن يرد قوله تعالى: ﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾ [سورة طه: 5].","قال الشّيخ الألبانيّ رحمه الله تعالى: ومن العجائب التي يقف العقل تجاهها حائراً أن يفتي بعض العلماء من المتقدّمين بأثر مجاهد هذا كما ذكره الذّهبيّ. ثم ذكر الخبر المذكور. انظر: الضّعيفة (865).","قلت: إن كان الأمر كما قال ابن عبدالبر والقرطبي والذهبي وغيرهم من أهل العلم قديماً ومن المعاصرين، فلا يقبل قول الآجري: أما حديث مجاهد في فضيلة النبيّ صلى الله عليه وسلم وتفسيره لهذه الآية أنه يُقعده على العرش، فقد تلقاها الشيوخ من أهل العلم والنقل لحديث رسول الله صلى الله عليه وسلم تلقوها بأحسن تلقٍ، وقبلوها بأحسن قبول، ولم ينكروها. وأنكروا على من ردّ حديث مجاهد إنكاراً شديداً، وقالوا: من ردّ حديث مجاهد فهو رجل سوءانتهى.","لأنّ الأمور الغيبية لا تثبت بالرّوايات الموقوفة الضّعيفة وقد ثبت بالرّوايات الصّحيحة المرفوعة والموقوفة أن المقام المحمود هو الشّفاعة الكبرى، فوجب المصير إليه وبه قال جماعة من الصحابة والتابعين وهم أعلم بمجاهد وغيره، بل قد نُقل عن مجاهد نفسه أنّ المقام المحمود هو الشّفاعة. أخرجه ابن جرير في تفسيره (15/45) عن محمد بن عمرو، قال: ثنا أبو عاصم، قال: عيسى، وحدّثني الحارث، قال: ثنا الحسن، قال: ثنا ورقاء جميعاً عن ابن أبي نجيح، عن مجاهد في قوله تعالى: ﴿مَقَامًا مَحْمُودًا﴾ قال: شفاعة محمد صلى الله عليه وسلم يوم القيامة.","وأمّا من قال بقول مجاهد فلعلّه قال ذلك مغايظة الجهمية لأنّهم ينكرون أن يكون شيء على العرش، كما قال أبو داود السّجستانيّ بعد أن رواه عن إبراهيم بن موسى الرّازيّ، قال: ثنا محمد بن فضيل، عن ليث، عن مجاهد في قوله تعالى: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ قال: يجلسه على عرشه.","قال أبو داود: من أنكر هذا فهو عندنا متّهم. وقال: ما زال النّاس يحدّثون بهذا يريدون مغايظة الجهميّة، وذلك أنّ الجهميّة ينكرون أن على العرش شيئاً. رواه الخلاّل في السنة (244)، وفي إسناده ليث وهو ابن أبي سليم صدوق اختلط أخيراً ولم يتميز حديثه فترك.","ولكن لا إحالة في قبول هذا الخبر لو ثبت كما قال ابن جرير الطّبريّ بعد أن صوَّب بأنّ المقام المحمود هو الشّفاعة، قال: وهذا وإن كان هو الصحيح من القول في تأويل قوله: ﴿عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾ لما ذكرنا من الرواية عن رسول الله صلى الله عليه وسلم وأصحابه والتابعين، فإنّ ما قاله مجاهد من أنّ الله يُقعد محمداً صلى الله عليه وسلم على عرشه، قول غير مدفوع صحته، لا من جهة خبر ولا نظر، وذلك لأنّه لا خبر عن رسول الله صلى الله عليه وسلم، ولا عن أحد من أصحابه، ولا عن التابعين بإحالة ذلك انتهى."],"301":["رُوي فيه عن أبي الدّرداء قال: قال رسول الله صلى الله عليه وسلم: من صلّى عليَّ حين يصبح عشراً، أو حين يمسي عشراً، أدركتْهُ شفاعتي.","رواه الطّبرانيّ في الكبير عن محمد بن علي بن حبيب الطّرائفيّ الرّقيّ، حدّثنا محمد بن علي بن ميمون، حدّثنا سليمان بن عبدالله الرّقيّ، حدّثنا بقية بن الوليد، عن إبراهيم بن محمد بن زياد، قال: سمعت خالد بن معدان يحدّث عن أبي الدّرداء، فذكره.","أورده ابن القيم في جلاء الأفهام (ص212، 213) وإسناده منقطع فإن خالد بن معدان لم يسمع من أبي الدّرداء، وفيه بقية بن الوليد وهو مدلّس تدليس التسوية ولم يصرح بالتحديث.","قال السّخاويّ في القول البديع (ص127): رواه الطبرانيّ بإسنادين أحدهما جيد، لكن فيه انقطاع، لأنّ خالد بن معدان لم يسمع من أبي الدّرداء، وأخرجه ابن أبي عاصم، وفيه ضعف."],"306":["قال الله تعالى: ﴿يَوْمَ يُنْفَخُ فِي الصُّورِ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ﴾ [سورة الأنعام: 73].","وقال تعالى: ﴿وَنُفِخَ فِي الصُّورِ فَجَمَعْنَاهُمْ جَمْعًا﴾ [سورة الكهف: 99].","وقال تعالى: ﴿يَوْمَ يُنْفَخُ فِي الصُّورِ وَنَحْشُرُ الْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا﴾ [سورة طه: 102].","وقال تعالى: ﴿فَإِذَا نُفِخَ فِي الصُّورِ فَلَا أَنْسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَاءَلُونَ﴾ [سورة المؤمنون: 101].","وقال تعالى: ﴿وَيَوْمَ يُنْفَخُ فِي الصُّورِ فَفَزِعَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ وَكُلٌّ أَتَوْهُ دَاخِرِينَ﴾ [سورة النمل: 87].","وقال تعالى: ﴿وَنُفِخَ فِي الصُّورِ فَإِذَا هُمْ مِنَ الْأَجْدَاثِ إِلَى رَبِّهِمْ يَنْسِلُونَ﴾ [سورة يس: 51].","وقال تعالى: ﴿وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَى فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ﴾ [سورة الزمر: 68].","وقال تعالى: ﴿وَنُفِخَ فِي الصُّورِ ذَلِكَ يَوْمُ الْوَعِيدِ﴾ [سورة ق: 20].","وقال تعالى: ﴿فَإِذَا نُفِخَ فِي الصُّورِ نَفْخَةٌ وَاحِدَةٌ﴾ [سورة الحاقة: 13].","وقال تعالى: ﴿يَوْمَ يُنْفَخُ فِي الصُّورِ فَتَأْتُونَ أَفْوَاجًا﴾ [سورة النبأ: 18].","قال مجاهد: الصُّور كهيئة البوق.","وقوله تعالى: ﴿فَإِذَا نُقِرَ فِي النَّاقُورِ﴾ [سورة المدثر: 8].","قال ابن عباس: الصُّور.","وقوله تعالى: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾ النّفخة الأولى و ﴿تَتْبَعُهَا الرَّادِفَةُ﴾ النّفخة الثّانية [سورة النّازعات: 6ـ 7] قاله ابن عباس."],"307":["لقد ادّعى الحليمي الإجماع على أنّ الذي ينفخ في الصّور هو إسرافيل كما ذكره الحافظ في فتحه (11/368)، ولكن لم يرد فيه حديث صحيح بأنّ إسرافيل هو الذي ينفخ في الصّور.","وأمّا الحديث المشهور بين الناس الذي يسمى بحديث الصّور، وإنّ إسرافيل قد التقم الصّور، وهو شاخص بصره إلى العرش ينتظر متى يؤمر، فهو حديث ضعيف وإن كان أورده كثير من أهل العلم في كتبهم.","وهو ما روي عن أبي هريرة، أنه قال: حدّثنا رسول الله صلى الله عليه وسلم، وهو في طائفة من أصحابه، فقال: إنّ الله تبارك وتعالى لما فرغ من خلق السماوات والأرض خلق الصُّور، فأعطاه إسرافيل عليه السلام فهو واضعه على فيه شاخص بصره إلى العرش ينتظر متى يؤمر. فقال أبو هريرة رضي الله عنه: يا رسول الله، وما الصُّور؟ قال: القرن. قلت: كيف هو؟ قال: عظيم! والذي نفسي بيده إنّ عظم دارة فيه كعرض السّماوات، وقال غيره: إنه قال: والأرض، ينفخ فيه ثلاث نفخات: الأولى: نفخة الفزع، والثانية: نفخة الصّعق، والثّالثة: نفخة القيام لربّ العالمين، يأمر الله عز وجل إسرافيل بالنفخة الأولى، فيقولُ له: انفخ نفخة الفزع، فيفزع له من في السماوات والأرض الا مَنْ شاء الله، ويأمره فيديمها ويطيلها ولا يفتر وهي التي يقول الله تبارك وتعالى: ﴿وَمَا يَنْظُرُ هَؤُلَاءِ إِلَّا صَيْحَةً وَاحِدَةً مَا لَهَا مِنْ فَوَاقٍ﴾ [سورة ص: 15]، فيسير الله الجبال فتمر مرّ السَّحاب ثم تكون ترابا ثم ترتج الأرض بأهلها رجّاً، وهي التي يقول الله تبارك وتعالى: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ تَتْبَعُهَا الرَّادِفَةُ قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ﴾ [سورة النازعات: 6، 8]، فتكون الأرض كالسّفينة المرتفعة في البحر تضربها الأمواج تكفأ بأهلها، وكالقنديل المعلّق بالعرش ترجحه الأرواح، فيبيد الناس عن ظهرها فتذهل المراضع، وتضع الحوامل، ويشيب الولدان، وتطير الشياطين هاربة حتى تأتي الأقطار فتلقاها الملائكة فتضرب وجوهها وترجع ويولي الناس مدبرين فبينا هم على ذلك إذ تصدّعت الأرض فانصدعت من قطر إلى قطر فرأوا أمراً عظيماً، فأخذهم لذلك من الكرب ما الله به عليم، ثم نظروا إلى السّماء فإذا هي كالمهل، ثم انشقّت من قطر إلى قطر، ثم انخسفت شمسها وقمرها قال رسول الله صلى الله عليه وسلم: والأموات لا يعلمون بشيء من ذلك. قال أبو هريرة رضي الله عنه: يا رسول الله؟ فمن استثنى الله عز وجل حين يقول: ﴿وَيَوْمَ يُنْفَخُ فِي الصُّورِ فَفَزِعَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ﴾ [سورة النمل: 87]؟ قال: أولئك الشّهداء وهم أحياء عند ربهم يرزقون، وإنما يصل الفزع إلى الأحياء فوقاهم الله فزع ذلك اليوم وأمّنهم منه، وهو عذاب الله يبعثه على شرار خلقه، وهو الذي يقول الله عز وجل: ﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّا أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى النَّاسَ سُكَارَى وَمَا هُمْ بِسُكَارَى وَلَكِنَّ عَذَابَ اللَّهِ شَدِيدٌ﴾ [سورة الحج: 1، 2]. فيمكثون في ذلك البلاء ما شاء الله إلا أنّه يطول، ثم يأمر الله عزّ وجلّ إسرافيل بنفخة الصَّعْق فينفخ نفخة الصّعق، فيصعق أهل السماوات والأرض إلاّ من شاء الله، فإذا هم خمدوا جاء ملك الموت عليه السلام إلى الجبّار تبارك وتعالى، فيقول: يا ربّ، قد مات أهل السماوات والأرض إلاّ مَنْ شئتَ، فيقول الله عزّ وجلّ، وهو أعلم ،: فمن بقي؟ فيقول: يا ربّ بقيتَ أنت الحي الذي لا يموت، وبقي حملة عرشك وبقى جبريل وميكائيل وأنا. فيقول الله عز وجل: ليمت جبريل وميكائيل. فيتكلّم العرش فيقول: يا رب، تميتُ جبريل وميكائيل؟ فيقول الله عزّ وجلّ: اسكت فإنّي كتبتُ على كل مَنْ تحت عرشي الموت، فيموتان، ويأتي ملك الموت عليه السّلام إلى الجبّار تبارك وتعالى، فيقول: قد مات جبريل وميكائيل، فيقول الله عز وجل، والله أعلم، فمن بقى؟ فيقول: يا ربّ بقيت أنت الحي الذي لا يموت، وبقي حملةُ عرشك، وبقيتُ أنا. فيقول الله عز وجل: ليمتْ حملة عرشي، فيموتون، ثم يأتي ملك الموت إلى الجبّار تبارك وتعالى، فيقول: يا ربّ، قد مات حملةُ عرشك، فيقول الله عز وجل، وهو أعلم ،: فمن بقي؟ فيقول: يا رب، بقيتَ أنت الحي الذي لا يموت، وبقيتُ أنا، فيقول الله عز وجل له: أنت من خلقي، خلقتُك لما رأيتَ، فَمُتْ فيموتُ، فإذا لم يبق إلا الله الواحد الأحد الصمد ليس بوالد ولا ولد، كان آخراً كما كان أوّلاً قال: لا موت على أهل الجنّة، ولا موت لأهل النّار، ثم يطوي الله تبارك وتعالى السماوات والأرض كطيّ السّجل، ثم دحاها ثم يلففها، ثم قال: أنا الجبّار، ثم هتف بصوته تبارك وتعالى وتقدّس، فقال: ﴿لِمَنِ الْمُلْكُ الْيَوْمَ﴾ ثم قال: ﴿لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾ [سورة غافر: 16] .... الحديث بطوله.","رواه أبو الشّيخ في العظمة (386)، واللّفظ له، وأبو القاسم الطبرانيّ في الأحاديث الطوال (36)، والبيهقيّ في البعث (609) كلّهم من طريق إسماعيل بن رافع، عن محمد بن يزيد، عن محمد بن كعب، عن أبي هريرة، فذكره.","قال الحافظ ابن كثير في تفسير سورة الأنعام (آية: 73): هذا حديث غريب جداً، ولبعضه شواهد في الأحاديث المتفرقة، وفي بعض ألفاظه نكارة، تفرّد به إسماعيل بن رافع قاص أهل المدينة، وقد اختلف فيه، فمنهم من وثّقه، ومنهم من ضعّفه. ونصّ على نكارة حديثه غير واحد من الأئمّة كأحمد بن حنبل، وأبي حاتم الرّازيّ، وعمرو بن علي الفلاس. ومنهم من قال فيه: هو متروك. وقال ابن عدي: أحاديثه كلّها فيها نظر، إلاّ أنه يكتب حديثه في جملة الضّعفاء.","وقال ابن كثير أيضاً: وقد اختلف عليه في إسناد هذا الحديث على وجوه كثيرة قد أفردتها في جزء على حدة، وأما سياقه فغريب جداً، ويقال: إنّه جمعه من أحاديث كثيرة وجعله سياقاً واحداً، فأنكر عليه بسبب ذلك انتهى.","ونقل أيضاً ابنُ عديّ عن البخاريّ أنّه قال: وروى إسماعيل بن رافع، عن محمد بن يزيد بن أبي زياد، عن رجل، عن محمد بن كعب حديث الصُّور مرسل لا يصح. انتهى انظر: الكامل (1/278).","وقال الحافظ: اضطرب في سنده مع ضعفه، فرواه عن محمد بن كعب القرظيّ تارة بلا واسطة، وتارة بواسطة رجل مبهم ومحمد، عن أبي هريرة، تارة بلا واسطة، وتارة بواسطة رجل من الأنصار مبهم أيضاً. وأخرجه إسماعيل ابن أبي زياد الشّاميّ أحد الضّعفاء أيضاً في تفسيره عن محمد بن عجلان، عن محمد بن كعب القرظيّ. واعترض مغلطاي على عبدالحقّ في تضعيفه الحديث بإسماعيل بن رافع، وخفي عليه أنّ الشّامي أضعف منه، ولعلّه سرقه منه، فألصقه بابن عجلان. الفتح (11/368).","وكذلك ذكر أبو الشّيخ آثاراً عن التابعين وأتباعهم في كون إسرافيل هو الذي ينفخ في الصور ومع كونها موقوفة عليهم فإن في أسانيدهم ضعفاً شديداً."],"310":["قال الله تعالى: ﴿وَنَحْشُرُهُمْ يَوْمَ الْقِيَامَةِ عَلَى وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَأْوَاهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا﴾ [سورة الإسراء: 97].","وقال تعالى: ﴿الَّذِينَ يُحْشَرُونَ عَلَى وُجُوهِهِمْ إِلَى جَهَنَّمَ أُولَئِكَ شَرٌّ مَكَانًا وَأَضَلُّ سَبِيلًا﴾ [سورة الفرقان: 34]."],"319":["قال الله تعالى: ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا إِنَّ ذَلِكَ عَلَى اللَّهِ يَسِيرٌ﴾ [سورة الحديد: 22].","وقال تعالى: ﴿سُنَّةَ اللَّهِ فِي الَّذِينَ خَلَوْا مِنْ قَبْلُ وَكَانَ أَمْرُ اللَّهِ قَدَرًا مَقْدُورًا﴾ [سورة الأحزاب: 38].","قال مالك بن أنس: ما أضلّ من كذب بالقدر، لو لم يكن عليهم فيه حجّة إلاّ قوله تعالى: ﴿هُوَ الَّذِي خَلَقَكُمْ فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾ [سورة التّغابن: 2] لكفى بها حجّة."],"330":["قال الله تعالى: ﴿وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ﴾ [سورة الأعراف: 34].","وقال تعالى: ﴿وَمَا يُعَمَّرُ مِنْ مُعَمَّرٍ وَلَا يُنْقَصُ مِنْ عُمُرِهِ إِلَّا فِي كِتَابٍ﴾ [سورة فاطر: 11].","قال الزّهريّ: فنرى أنّه إذا حضر أجلُه، فلا يؤخَّرُ ساعةً ولا يقدّم. وما لم يحضر أجلُه فإنّ الله يؤخِّر ما شاء ويقدِّم ما شاء. انظر: القدر (442) للفريابي."],"335":["قال الله تعالى: ﴿وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالْإِنْسِ لَهُمْ قُلُوبٌ لَا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَا يُبْصِرُونَ بِهَا وَلَهُمْ آذَانٌ لَا يَسْمَعُونَ بِهَا أُولَئِكَ كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ أُولَئِكَ هُمُ الْغَافِلُونَ﴾ [سورة الأعراف: 179].","وقال تعالى: ﴿وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ إِلَّا مَنْ رَحِمَ رَبُّكَ وَلِذَلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ﴾ [سورة هود: 118، 119]."],"337":["قال الله تعالى: ﴿أَوَمَنْ كَانَ مَيْتًا فَأَحْيَيْنَاهُ وَجَعَلْنَا لَهُ نُورًا يَمْشِي بِهِ فِي النَّاسِ كَمَنْ مَثَلُهُ فِي الظُّلُمَاتِ لَيْسَ بِخَارِجٍ مِنْهَا﴾ [سورة الأنعام: 122]."],"338":["قال الله تعالى: ﴿وَأَمَّا الْغُلَامُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَا أَنْ يُرْهِقَهُمَا طُغْيَانًا وَكُفْرًا فَأَرَدْنَا أَنْ يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِنْهُ زَكَاةً وَأَقْرَبَ رُحْمًا﴾ [سورة الكهف: 80 – 81]."],"340":["رُوِيَ عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي يَدِهِ كِتَابَانِ، فَقَالَ: أَتَدْرُونَ مَا هَذَانِ الْكِتَابَانِ؟ فَقُلْنَا: لَا يَا رَسُولَ اللَّهِ، إِلَّا أَنْ تُخْبِرَنَا، فَقَالَ لِلَّذِي فِي يَدِهِ الْيُمْنَى: هَذَا كِتَابٌ مِنْ رَبِّ الْعَالَمِينَ، فِيهِ أَسْمَاءُ أَهْلِ الْجَنَّةِ وَأَسْمَاءُ آبَائِهِمْ وَقَبَائِلِهِمْ، ثُمَّ أُجْمِلَ عَلَى آخِرِهِمْ، فَلَا يُزَادُ فِيهِمْ وَلَا يُنْقَصُ مِنْهُمْ أَبَدًا، ثُمَّ قَالَ لِلَّذِي فِي شِمَالِهِ: هَذَا كِتَابٌ مِنْ رَبِّ الْعَالَمِينَ، فِيهِ أَسْمَاءُ أَهْلِ النَّارِ وَأَسْمَاءُ آبَائِهِمْ وَقَبَائِلِهِمْ، ثُمَّ أُجْمِلَ عَلَى آخِرِهِمْ فَلَا يُزَادُ فِيهِمْ وَلَا يُنْقَصُ مِنْهُمْ أَبَدًا، فَقَالَ أَصْحَابُهُ: فَفِيمَ الْعَمَلُ يَا رَسُولَ اللَّهِ، إِنْ كَانَ أَمْرٌ قَدْ فُرِغَ مِنْهُ، فَقَالَ: سَدِّدُوا وَقَارِبُوا فَإِنَّ صَاحِبَ الْجَنَّةِ يُخْتَمُ لَهُ بِعَمَلِ أَهْلِ الْجَنَّةِ، وَإِنْ عَمِلَ أَيَّ عَمَلٍ، وَإِنَّ صَاحِبَ النَّارِ يُخْتَمُ لَهُ بِعَمَلِ أَهْلِ النَّارِ، وَإِنْ عَمِلَ أَيَّ عَمَلٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدَيْهِ فَنَبَذَهُمَا، ثُمَّ قَالَ: فَرَغَ رَبُّكُمْ مِنَ الْعِبَادِ، ﴿فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ﴾ .","رواه التّرمذيّ (2141) عن قتيبة، عن ليث، عن أبي قبيل، عن شُفيّ بن ماتع، عن عبدالله بن عمرو بن العاص، قال: فذكره.","ثم رواه أيضاً عن قتيبة، حدّثنا بكر بن مضر، عن أبي قبيل، نحوه.","ورواه كلٌّ من الإمام أحمد (6563)، وابن وهب في القدر (13)، والفريابيّ في القدر (45)، وابن أبي عاصم في السنة (348)، والبيهقيّ في القضاء والقدر (1/252، 253، 327) كلّهم من طرق عن أبي قبيل المعافريّ، بإسناده مثله. إلاّ أنّ ابن وهب لم يُسمِّ الصّحابيّ.","قال التّرمذيّ: حسن غريب صحيح. وقال: أبو قبيل اسمه حُيي بن هانئ.","قلت: أبو قبيل هذا فيه كلام من أهل العلم، وقد قيل: إنه كان يكثر النقل عن الكتب القديمة، كما في التعجيل، فمثله لا يقبل تفرده في مثل هذه الأمور العظيمة التي تتوفر الدواعي على نقلها، وإذا روى الثقة المأمون خبرا تتوفر الدواعي على نقله لا يقبل تفرده، فكيف بمن هو دونه.","ورواه البيهقيّ في القضاء والقدر (1/254، 255) من وجه آخر عن عبدالله بن عمرو بن العاص، وكان النّبيّ صلى الله عليه وسلم يفضّل عبدالله على أبيه، قال: خرج علينا رسولُ الله صلى الله عليه وسلم ذات يوم قابضاً على كفيه، ومعه كتابان. فقال: هذا كتابٌ من ربِّ العالمين فذكر الحديث بمعناه يزيد وينقص، ومما زاد، قال: قبل أن يستقروا نطفاً في الأصلاب، وقبل أن يصيروا نطفاً في الأرحام، إذ هم في الطّينة منجدلون، فليس زائد فيهم ولا ناقص منهم إجمال من الله عليهم إلى يوم القيامة. وقال في آخره: عدل من الله عزّ وجلّ.","أخرجه من طريق بشر بن زكريّا، حدّثنا سعيد بن سنان، عن أبي الزّاهريّة، حدير بن كريب، عن عبدالله بن عمرو بن العاص، فذكر مثله، إلاّ أنّ فيه سعيد بن سنان وهو أبو مهدي الحنفيّ الكنديّ ضعيف جدّاً.","قال ابن عدي: وعامّة ما يرويه، وخاصّة عن أبي الزّاهرية غير محفوظ.","وروي أيضا عن ابن عباس، قال: خرج النّبيُّ صلى الله عليه وسلم فسمع ناساً من أصحابه يذكرون القدر، فقال: إنّكم قد أخذتم في شعبتين بعيدتي الغور، فيهما هلك أهل الكتاب من قبلكم. ولقد أخرج يوماً كتاباً، قال وهو يقرأ: هذا كتابٌ من الله الرحمن الرّحيم، فيه تسمية أهل الجنّة بأسمائهم، وأسماء أبائهم وقبائلهم وعشائرهم، لا ينقص منهم أحدٌ، فريقٌ في الجنّة، وفريق في السّعير.","رواه ابنُ بطّة في الإبانة (1277)، واللالكائيّ في أصول الاعتقاد (1083) كلاهما من حديث ابن وهب، قال: أخبرنا عبدالرحمن بن سلمان، عن عقيل، عن عكرمة، عن ابن عباس، فذكر مثله.","واللّفظ للالكائيّ، وأمّا ابن بطّة فلم يسق لفظه كاملاً.","وفيه عبدالرحمن بن سلمان وهو الحجري الرُّعيني المصريّ وهو وإن كان من رجال مسلم فقد ذكره البخاري في الضعفاء وقال: فيه نظر، وقال ابن يونس: يروي عن عقيل غرائب ينفرد بها، وهذا من روايته عنه.","وكذلك لا يصح ما رُوي عن ابن عمر، قال: خرج علينا رسولُ الله صلى الله عليه وسلم قابضاً على شيء في يده، ففتح يده اليمنى، فقال: بسم الله الرحمن الرحيم، كتاب ﴿من الرّحمن الرّحيم﴾، فيه أهل الجنّة بأعدادهم وأسمائهم وأحسابهم، يُجمل عليهم إلى يوم القيامة، لا ينقص منهم أحد، ولا يُزاد فيهم أحد، وقد يُسلك بالسَّعيد طريقُ الشّقاء حتّى يقال: هو منهم، ما أشبهه بهم، ثم يزال إلى سعادته قبل موته ولو بفواق ناقة. وفتح يده اليسرى فقال: بسم الله الرحمن الرّحيم، كتابٌ ﴿من الرّحمن الرّحيم﴾، فيه أهلُ النّار بأعدادهم وأسمائهم وأحسابهم، يُجمل عليهم إلى يوم القيامة، لا يَنقص منهم ولا يُزاد فيهم أحد، وقد يسلك بالأشقياء طريقُ أهل السّعادة حتى يقال: هو منهم، وما أشبهه بهم، ثم يدرك أحدَهم شقاءُه قبل موته ولو بفواق ناقة، ثم قال رسولُ الله صلى الله عليه وسلم: العمل بخواتيمه، العمل بخواتيمه، ثلاثاً. فهو ضعيف.","رواه البزار - كشف الأستار (2156)، عن زياد بن يحيى أبي الخطّاب، ثنا عبدالله بن ميمون المكيّ، عن عبيد الله بن عمر، عن نافع، عن ابن عمر، فذكره.","ورواه اللالكائيّ في أصول الاعتقاد (1088) من وجه آخر عن عبدالله بن ميمون القداح بإسناده، مثله.","قال البزّار: لا نعلم رواه عن عبيد الله إلا عبدالله بن ميمون وهوصالح.","قلت: عبدالله بن ميمون القداح ليس بصالح، بل أهل العلم مطبقون على تضعيفه حتى قال الحاكم: روى عن عبيدالله بن عمر أحاديث موضوعة. ومن أجله ضعّفه الهيثميّ في المجمع (11919).","وفي الباب أحاديث عن البراء بن عازب، وابن عباس، وعبدالله بن بسر، وعلي بن أبي طالب كلها ضعيفة."],"354":["قال الله تعالى: ﴿وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَا أَلَتْنَاهُمْ مِنْ عَمَلِهِمْ مِنْ شَيْءٍ﴾ [سورة الطّور: 21]."],"362":["قال الله تعالى: ﴿وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ﴾ [سورة الصافات: 96]."],"364":["قال الله تعالى: ﴿فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ فَتَحْنَا عَلَيْهِمْ أَبْوَابَ كُلِّ شَيْءٍ حَتَّى إِذَا فَرِحُوا بِمَا أُوتُوا أَخَذْنَاهُمْ بَغْتَةً فَإِذَا هُمْ مُبْلِسُونَ﴾ [الأنعام: 44].","وقال تعالى: ﴿فَذَرْنِي وَمَنْ يُكَذِّبُ بِهَذَا الْحَدِيثِ سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لَا يَعْلَمُونَ﴾ [سورة القلم: 44]."]});